/* Contenus d'exemple de Codes & articles, Fiches d'arrêt et Fiches mémo, pour la recherche commune (fouille.js).
   Générés par scripts/recherche/exemples.mjs depuis les pages des outils — ne pas modifier ici. */
window.PARAPHE_EXEMPLES = {"codes":[{"id":"seed-art-0","matiere":"Droit public des affaires","code":"Constitution du 4 octobre 1958","numero":"34","texte":"La loi fixe également les règles concernant :\n[…]\n– la création de catégories d'établissements publics ;\n[…]\n– les nationalisations d'entreprises et les transferts de propriété d'entreprises du secteur public au secteur privé.","note":"Fonde la compétence du législateur sur les grandes opérations touchant au secteur public économique."},{"id":"seed-art-1","matiere":"Droit public des affaires","code":"Code de la commande publique","numero":"L2","texte":"Sont des contrats de la commande publique les contrats conclus à titre onéreux par un acheteur ou une autorité concédante, pour répondre à ses besoins en matière de travaux, de fournitures ou de services, avec un ou plusieurs opérateurs économiques.\nLes contrats de la commande publique sont les marchés publics et les concessions définis au livre Ier de la première partie, quelle que soit leur dénomination. Ils sont régis par le présent code et, le cas échéant, par des dispositions particulières.","note":"Article d'entrée du code : distingue les deux grandes familles de contrats de la commande publique."},{"id":"seed-art-2","matiere":"Droit public des affaires","code":"Code général des collectivités territoriales","numero":"L1411-1","texte":"Les collectivités territoriales, leurs groupements ou leurs établissements publics peuvent confier la gestion d'un service public dont elles ont la responsabilité à un ou plusieurs opérateurs économiques par une convention de délégation de service public définie à l'article L. 1121-3 du code de la commande publique préparée, passée et exécutée conformément à la troisième partie de ce code.","note":"Notion aujourd'hui reprise par la catégorie des concessions de service dans le Code de la commande publique (2019) — vérifier la numérotation en vigueur."},{"id":"seed-art-3","matiere":"Droit public des affaires","code":"Code général de la propriété des personnes publiques","numero":"L2111-1","texte":"Sous réserve de dispositions législatives spéciales, le domaine public d'une personne publique mentionnée à l'article L. 1 est constitué des biens lui appartenant qui sont soit affectés à l'usage direct du public, soit affectés à un service public pourvu qu'en ce cas ils fassent l'objet d'un aménagement indispensable à l'exécution des missions de ce service public.","note":"Définition légale du domaine public, issue de la codification de 2006."},{"id":"seed-art-4","matiere":"Droit des sociétés","code":"Code civil","numero":"1832","texte":"La société est instituée par deux ou plusieurs personnes qui conviennent par un contrat d'affecter à une entreprise commune des biens ou leur industrie en vue de partager le bénéfice ou de profiter de l'économie qui pourra en résulter.\nElle peut être instituée, dans les cas prévus par la loi, par l'acte de volonté d'une seule personne.\nLes associés s'engagent à contribuer aux pertes.","note":"Définition matricielle de la société, valable pour toutes les formes sociales."},{"id":"seed-art-5","matiere":"Droit des sociétés","code":"Code civil","numero":"1833","texte":"Toute société doit avoir un objet licite et être constituée dans l'intérêt commun des associés.\nLa société est gérée dans son intérêt social, en prenant en considération les enjeux sociaux et environnementaux de son activité.","note":"Deuxième alinéa issu de la loi PACTE (2019) : introduit la prise en compte des enjeux sociaux et environnementaux."},{"id":"seed-art-6","matiere":"Droit des sociétés","code":"Code de commerce","numero":"L210-6","texte":"Les sociétés commerciales jouissent de la personnalité morale à dater de leur immatriculation au registre du commerce et des sociétés. La transformation régulière d'une société n'entraîne pas la création d'une personne morale nouvelle. Il en est de même de la prorogation.\nLes personnes qui ont agi au nom d'une société en formation avant qu'elle ait acquis la jouissance de la personnalité morale sont tenues solidairement et indéfiniment responsables des actes ainsi accomplis, à moins que la société, après avoir été régulièrement constituée et immatriculée, ne reprenne les engagements souscrits. Ces engagements sont alors réputés avoir été souscrits dès l'origine par la société.","note":"Marque le moment de naissance de la personnalité morale — avant, on parle de société en formation."},{"id":"seed-art-7","matiere":"Droit des sociétés","code":"Code de commerce","numero":"L223-1","texte":"La société à responsabilité limitée est instituée par une ou plusieurs personnes qui ne supportent les pertes qu'à concurrence de leurs apports.\nLorsque la société ne comporte qu'une seule personne, celle-ci est dénommée \"associé unique\". L'associé unique exerce les pouvoirs dévolus à l'assemblée des associés par les dispositions du présent chapitre. Un décret fixe un modèle de statuts types de société à responsabilité limitée dont l'associé unique, personne physique, assume personnellement la gérance et les conditions dans lesquelles ces statuts sont portés à la connaissance de l'intéressé. Ces statuts types s'appliquent à moins que l'intéressé ne produise des statuts différents lors de sa demande d'immatriculation de la société.\nLa société à responsabilité limitée dont l'associé unique, personne physique, assume personnellement la gérance est soumise à des formalités de publicité allégées déterminées par décret en Conseil d'Etat. Ce décret prévoit les conditions de dispense d'insertion au Bulletin officiel des annonces civiles et commerciales. (1)\nLa société est désignée par une dénomination sociale, à laquelle peut être incorporé le nom d'un ou plusieurs associés, et qui doit être précédée ou suivie immédiatement des mots \"société à responsabilité limitée\" ou des initiales \"SARL\" et de l'énonciation du capital social.\nLes sociétés d'assurance, de capitalisation et d'épargne ne peuvent adopter la forme de société à responsabilité limitée.","note":"Définition de la SARL (et de l'EURL lorsqu'un seul associé)."},{"id":"seed-art-8","matiere":"Droit des sociétés","code":"Code de commerce","numero":"L227-1","texte":"Une société par actions simplifiée peut être instituée par une ou plusieurs personnes qui ne supportent les pertes qu'à concurrence de leur apport.\nLorsque cette société ne comporte qu'une seule personne, celle-ci est dénommée \" associé unique \". L'associé unique exerce les pouvoirs dévolus aux associés lorsque le présent chapitre prévoit une prise de décision collective.\nDans la mesure où elles sont compatibles avec les dispositions particulières prévues par le présent chapitre, les règles concernant les sociétés anonymes, à l'exception de l'article L. 224-2, du second alinéa de l'article L. 225-14, des articles L. 225-17 à L. 225-102, L. 225-103 à L. 225-126, L. 225-243, du I de l'article L. 233-8 et de l'article L. 236-17, sont applicables à la société par actions simplifiée. Pour l'application de ces règles, les attributions du conseil d'administration ou de son président sont exercées par le président de la société par actions simplifiée ou celui ou ceux de ses dirigeants que les statuts désignent à cet effet.\nLa société par actions simplifiée peut émettre des actions inaliénables résultant d'apports en industrie tels que définis à l'article 1843-2 du code civil. Les statuts déterminent les modalités de souscription et de répartition de ces actions.\nPar dérogation au premier alinéa de l'article L. 225-14, les futurs associés peuvent décider à l'unanimité que le recours à un commissaire aux apports ne sera pas obligatoire, lorsque la valeur d'aucun apport en nature n'excède un montant fixé par décret et si la valeur totale de l'ensemble des apports en nature non soumis à l'évaluation d'un commissaire aux apports n'excède pas la moitié du capital.\nLorsque la société est constituée par une seule personne, le commissaire aux apports est désigné par l'associé unique. Toutefois le recours à un commissaire aux apports n'est pas obligatoire si les conditions prévues au cinquième alinéa du présent article sont réunies ou si l'associé unique, personne physique, exerçant son activité professionnelle en nom propre avant la constitution de la société, y compris sous le régime prévu aux articles L. 526-6 à L. 526-21, apporte des éléments qui figuraient dans le bilan de son dernier exercice.\nLorsqu'il n'y a pas eu de commissaire aux apports ou lorsque la valeur retenue est différente de celle proposée par le commissaire aux apports, les associés sont solidairement responsables pendant cinq ans, à l'égard des tiers, de la valeur attribuée aux apports en nature lors de la constitution de la société.\nLa société par actions simplifiée dont l'associé unique, personne physique, assume personnellement la présidence est soumise à des formalités de publicité allégées déterminées par décret en Conseil d'Etat. Ce décret prévoit les conditions de dispense d'insertion au Bulletin officiel des annonces civiles et commerciales.","note":"Définition de la SAS (et de la SASU) — grande liberté statutaire dans l'organisation des pouvoirs."},{"id":"seed-art-9","matiere":"Droit du travail","code":"Code du travail","numero":"L1221-1","texte":"Le contrat de travail est soumis aux règles du droit commun. Il peut être établi selon les formes que les parties contractantes décident d'adopter.","note":"Pas de formalisme imposé : le contrat de travail peut être écrit ou verbal (sauf CDD, temps partiel...)."},{"id":"seed-art-10","matiere":"Droit du travail","code":"Code du travail","numero":"L1231-1","texte":"Le contrat de travail à durée indéterminée peut être rompu à l'initiative de l'employeur ou du salarié, ou d'un commun accord, dans les conditions prévues par les dispositions du présent titre.\nCes dispositions ne sont pas applicables pendant la période d'essai.","note":"Article d'ouverture du titre relatif à la rupture du contrat de travail (licenciement, démission, rupture conventionnelle...)."},{"id":"seed-art-11","matiere":"Droit du travail","code":"Code du travail","numero":"L1232-1","texte":"Tout licenciement pour motif personnel est motivé dans les conditions définies par le présent chapitre.\nIl est justifié par une cause réelle et sérieuse.","note":"Fondement textuel de l'exigence de cause réelle et sérieuse."},{"id":"seed-art-12","matiere":"Droit du travail","code":"Code du travail","numero":"L3121-27","texte":"La durée légale de travail effectif des salariés à temps complet est fixée à trente-cinq heures par semaine.","note":"Durée légale, non maximale : les heures effectuées au-delà sont en principe des heures supplémentaires majorées."},{"id":"seed-art-13","matiere":"Libertés fondamentales","code":"Déclaration des droits de l'homme et du citoyen (1789)","numero":"1er","texte":"Les hommes naissent et demeurent libres et égaux en droits. Les distinctions sociales ne peuvent être fondées que sur l'utilité commune.","note":"Fondement textuel du principe d'égalité, à valeur constitutionnelle."},{"id":"seed-art-14","matiere":"Libertés fondamentales","code":"Déclaration des droits de l'homme et du citoyen (1789)","numero":"4","texte":"La liberté consiste à pouvoir faire tout ce qui ne nuit pas à autrui : ainsi, l'exercice des droits naturels de chaque homme n'a de bornes que celles qui assurent aux autres Membres de la Société la jouissance de ces mêmes droits. Ces bornes ne peuvent être déterminées que par la Loi.","note":"Définition classique de la liberté, souvent citée pour introduire la théorie des libertés publiques."},{"id":"seed-art-15","matiere":"Libertés fondamentales","code":"Déclaration des droits de l'homme et du citoyen (1789)","numero":"11","texte":"La libre communication des pensées et des opinions est un des droits les plus précieux de l'Homme : tout Citoyen peut donc parler, écrire, imprimer librement, sauf à répondre de l'abus de cette liberté dans les cas déterminés par la Loi.","note":"Fondement constitutionnel de la liberté d'expression et de la presse."},{"id":"seed-art-16","matiere":"Libertés fondamentales","code":"Convention EDH","numero":"8","texte":"1. Toute personne a droit au respect de sa vie privée et familiale, de son domicile et de sa correspondance.\n2. Il ne peut y avoir ingérence d'une autorité publique dans l'exercice de ce droit que pour autant que cette ingérence est prévue par la loi et qu'elle constitue une mesure qui, dans une société démocratique, est nécessaire à la sécurité nationale, à la sûreté publique, au bien-être économique du pays, à la défense de l'ordre et à la prévention des infractions pénales, à la protection de la santé ou de la morale, ou à la protection des droits et libertés d'autrui.","note":"Article très mobilisé par la CEDH (vie privée, filiation, données personnelles, expulsion des étrangers...)."},{"id":"seed-art-17","matiere":"Libertés fondamentales","code":"Convention EDH","numero":"10","texte":"1. Toute personne a droit à la liberté d'expression. Ce droit comprend la liberté d'opinion et la liberté de recevoir ou de communiquer des informations ou des idées sans qu'il puisse y avoir ingérence d'autorités publiques et sans considération de frontière. Le présent article n'empêche pas les États de soumettre les entreprises de radiodiffusion, de cinéma ou de télévision à un régime d'autorisations.\n2. L'exercice de ces libertés comportant des devoirs et des responsabilités peut être soumis à certaines formalités, conditions, restrictions ou sanctions prévues par la loi, qui constituent des mesures nécessaires, dans une société démocratique, à la sécurité nationale, à l'intégrité territoriale ou à la sûreté publique, à la défense de l'ordre et à la prévention du crime, à la protection de la santé ou de la morale, à la protection de la réputation ou des droits d'autrui, pour empêcher la divulgation d'informations confidentielles ou pour garantir l'autorité et l'impartialité du pouvoir judiciaire.","note":"Complète l'article 11 DDHC au niveau conventionnel européen."},{"id":"seed-art-18","matiere":"Libertés fondamentales","code":"Constitution du 4 octobre 1958","numero":"66","texte":"Nul ne peut être arbitrairement détenu.\nL'autorité judiciaire, gardienne de la liberté individuelle, assure le respect de ce principe dans les conditions prévues par la loi.","note":"Fondement du rôle protecteur du juge judiciaire à l'égard de la liberté individuelle (détention, garde à vue...)."},{"id":"seed-art-19","matiere":"Procédure pénale","code":"Code de procédure pénale","numero":"préliminaire","texte":"I.-La procédure pénale doit être équitable et contradictoire et préserver l'équilibre des droits des parties.\nElle doit garantir la séparation des autorités chargées de l'action publique et des autorités de jugement.\nLes personnes se trouvant dans des conditions semblables et poursuivies pour les mêmes infractions doivent être jugées selon les mêmes règles.\nII.-L'autorité judiciaire veille à l'information et à la garantie des droits des victimes au cours de toute procédure pénale.\nIII.-Toute personne suspectée ou poursuivie est présumée innocente tant que sa culpabilité n'a pas été établie. Les atteintes à sa présomption d'innocence sont prévenues, réparées et réprimées dans les conditions prévues par la loi.\nElle a le droit d'être informée des charges retenues contre elle et d'être assistée d'un défenseur.\nSi la personne suspectée ou poursuivie ne comprend pas la langue française, elle a droit, dans une langue qu'elle comprend et jusqu'au terme de la procédure, à l'assistance d'un interprète, y compris pour les entretiens avec son avocat ayant un lien direct avec tout interrogatoire ou toute audience, et, sauf renonciation expresse et éclairée de sa part, à la traduction des pièces essentielles à l'exercice de sa défense et à la garantie du caractère équitable du procès qui doivent, à ce titre, lui être remises ou notifiées en application du présent code.\nLes mesures de contraintes dont la personne suspectée ou poursuivie peut faire l'objet sont prises sur décision ou sous le contrôle effectif de l'autorité judiciaire. Elles doivent être strictement limitées aux nécessités de la procédure, proportionnées à la gravité de l'infraction reprochée et ne pas porter atteinte à la dignité de la personne.\nIl doit être définitivement statué sur l'accusation dont cette personne fait l'objet dans un délai raisonnable.\nAu cours de la procédure pénale, les mesures portant atteinte à la vie privée d'une personne ne peuvent être prises, sur décision ou sous le contrôle effectif de l'autorité judiciaire, que si elles sont, au regard des circonstances de l'espèce, nécessaires à la manifestation de la vérité et proportionnées à la gravité de l'infraction.\nToute personne condamnée a le droit de faire examiner sa condamnation par une autre juridiction.\nEn matière criminelle et correctionnelle, aucune condamnation ne peut être prononcée contre une personne sur le seul fondement de déclarations qu'elle a faites sans avoir pu s'entretenir avec un avocat et être assistée par lui.\nEn matière de crime ou de délit, le droit de se taire sur les faits qui lui sont reprochés est notifié à toute personne suspectée ou poursuivie avant tout recueil de ses observations et avant tout interrogatoire, y compris pour obtenir des renseignements sur sa personnalité ou pour prononcer une mesure de sûreté, lors de sa première présentation devant un service d'enquête, un magistrat, une juridiction ou toute personne ou tout service mandaté par l'autorité judiciaire. Aucune condamnation ne peut être prononcée sur le seul fondement de déclarations faites sans que ledit droit ait été notifié.\nLe respect du secret professionnel de la défense et du conseil, prévu à l'article 66-5 de la loi n° 71-1130 du 31 décembre 1971 portant réforme de certaines professions judiciaires et juridiques, est garanti au cours de la procédure pénale dans les conditions prévues par le présent code.","note":"Article-cadre énonçant les grands principes directeurs du procès pénal."},{"id":"seed-art-20","matiere":"Procédure pénale","code":"Code de procédure pénale","numero":"63","texte":"I.-Seul un officier de police judiciaire peut, d'office ou sur instruction du procureur de la République, placer une personne en garde à vue.\nDès le début de la mesure, l'officier de police judiciaire informe le procureur de la République, par tout moyen, du placement de la personne en garde à vue. Il lui donne connaissance des motifs justifiant, en application de l'article 62-2, ce placement et l'avise de la qualification des faits qu'il a notifiée à la personne en application du 2° de l'article 63-1. Le procureur de la République peut modifier cette qualification ; dans ce cas, la nouvelle qualification est notifiée à la personne dans les conditions prévues au même article 63-1.\nII.-La durée de la garde à vue ne peut excéder vingt-quatre heures.\nToutefois, la garde à vue peut être prolongée pour un nouveau délai de vingt-quatre heures au plus, sur autorisation écrite et motivée du procureur de la République, si l'infraction que la personne est soupçonnée d'avoir commise ou tenté de commettre est un crime ou un délit puni d'une peine d'emprisonnement supérieure ou égale à un an et si la prolongation de la mesure est l'unique moyen de parvenir à l'un au moins des objectifs mentionnés aux 1° à 6° de l'article 62-2 ou de permettre, dans les cas où il n'existe pas dans le tribunal de locaux relevant de l'article 803-3, la présentation de la personne devant l'autorité judiciaire.\nLe procureur de la République peut subordonner son autorisation à la présentation de la personne devant lui. Cette présentation peut être réalisée par l'utilisation d'un moyen de télécommunication audiovisuelle.\nIII.-Si, avant d'être placée en garde à vue, la personne a été appréhendée ou a fait l'objet de toute autre mesure de contrainte pour ces mêmes faits, l'heure du début de la garde à vue est fixée, pour le respect des durées prévues au II du présent article, à l'heure à partir de laquelle la personne a été privée de liberté. Si la personne n'a pas fait l'objet d'une mesure de contrainte préalable, mais que son placement en garde à vue est effectué dans le prolongement immédiat d'une audition, cette heure est fixée à celle du début de l'audition.\nSi une personne a déjà été placée en garde à vue pour les mêmes faits, la durée des précédentes périodes de garde à vue s'impute sur la durée de la mesure.","note":"Fondement légal de la garde à vue, mesure de contrainte encadrée depuis la réforme de 2011."},{"id":"seed-art-21","matiere":"Procédure pénale","code":"Code de procédure pénale","numero":"80-1","texte":"Le juge d'instruction ne peut mettre en examen que les personnes à l'encontre desquelles il existe des indices graves ou concordants rendant vraisemblable qu'elles aient pu participer, comme auteur ou comme complice, à la commission des infractions dont il est saisi.\nA peine de nullité, il ne peut procéder à cette mise en examen qu'après avoir préalablement entendu les observations de la personne ou l'avoir mise en mesure de les faire, en étant assistée par son avocat, soit dans les conditions prévues par l'article 116 relatif à l'interrogatoire de première comparution, soit en tant que témoin assisté conformément aux dispositions des articles 113-1 à 113-8.\nLe juge d'instruction ne peut procéder à la mise en examen de la personne que s'il estime ne pas pouvoir recourir à la procédure de témoin assisté.","note":"Encadre le pouvoir de mise en examen pour éviter les mises en cause trop précoces."},{"id":"seed-art-22","matiere":"Procédure pénale","code":"Code de procédure pénale","numero":"137","texte":"Toute personne mise en examen, présumée innocente, demeure libre.\nToutefois, en raison des nécessités de l'instruction ou à titre de mesure de sûreté, elle peut être astreinte à une ou plusieurs obligations du contrôle judiciaire ou, si celles-ci se révèlent insuffisantes, être assignée à résidence avec surveillance électronique.\nA titre exceptionnel, si les obligations du contrôle judiciaire ou de l'assignation à résidence avec surveillance électronique ne permettent pas d'atteindre ces objectifs, elle peut être placée en détention provisoire.","note":"Pose le principe de liberté et le caractère exceptionnel de la détention provisoire."},{"id":"seed-art-23","matiere":"Procédure pénale","code":"Code de procédure pénale","numero":"7 à 9","texte":"Art. 7 : L'action publique des crimes se prescrit par vingt années révolues à compter du jour où l'infraction a été commise.\n[…]\nArt. 8 : L'action publique des délits se prescrit par six années révolues à compter du jour où l'infraction a été commise.\n[…]\nArt. 9 : L'action publique des contraventions se prescrit par une année révolue à compter du jour où l'infraction a été commise.","note":"Délais issus de la réforme de la prescription pénale du 27 février 2017."},{"id":"seed-art-24","matiere":"Droit fiscal","code":"Livre des procédures fiscales","numero":"L64","texte":"Afin d'en restituer le véritable caractère, l'administration est en droit d'écarter, comme ne lui étant pas opposables, les actes constitutifs d'un abus de droit, soit que ces actes ont un caractère fictif, soit que, recherchant le bénéfice d'une application littérale des textes ou de décisions à l'encontre des objectifs poursuivis par leurs auteurs, ils n'ont pu être inspirés par aucun autre motif que celui d'éluder ou d'atténuer les charges fiscales que l'intéressé, si ces actes n'avaient pas été passés ou réalisés, aurait normalement supportées eu égard à sa situation ou à ses activités réelles.\nEn cas de désaccord sur les rectifications notifiées sur le fondement du présent article, le litige est soumis, à la demande du contribuable, à l'avis du comité de l'abus de droit fiscal. L'administration peut également soumettre le litige à l'avis du comité.\nLes avis rendus font l'objet d'un rapport annuel qui est rendu public.","note":"Texte fondateur de la procédure de répression des abus de droit fiscal (fictivité ou fraude à la loi)."},{"id":"seed-art-25","matiere":"Droit fiscal","code":"Code général des impôts","numero":"1729","texte":"Les inexactitudes ou les omissions relevées dans une déclaration ou un acte comportant l'indication d'éléments à retenir pour l'assiette ou la liquidation de l'impôt ainsi que la restitution d'une créance de nature fiscale dont le versement a été indûment obtenu de l'Etat entraînent l'application d'une majoration de :\na. 40 % en cas de manquement délibéré ;\nb. 80 % en cas d'abus de droit au sens de l'article L. 64 du livre des procédures fiscales ; elle est ramenée à 40 % lorsqu'il n'est pas établi que le contribuable a eu l'initiative principale du ou des actes constitutifs de l'abus de droit ou en a été le principal bénéficiaire ;\nc. 80 % en cas de manœuvres frauduleuses ou de dissimulation d'une partie du prix stipulé dans un contrat ou en cas d'application de l'article 792 bis.","note":"Sanctions applicables en cas de rectification fiscale, à moduler selon la gravité du manquement."},{"id":"seed-art-26","matiere":"Droit fiscal","code":"Livre des procédures fiscales","numero":"L169","texte":"Pour l'impôt sur le revenu et l'impôt sur les sociétés, le droit de reprise de l'administration des impôts s'exerce jusqu'à la fin de la troisième année qui suit celle au titre de laquelle l'imposition est due.\nPar exception aux dispositions du premier alinéa, le droit de reprise de l'administration s'exerce jusqu'à la fin de la dixième année qui suit celle au titre de laquelle l'imposition est due, lorsque le contribuable exerce une activité occulte ou lorsqu'il est bénéficiaire de revenus distribués par une personne morale exerçant une activité occulte. L'activité occulte est réputée exercée lorsque le contribuable ou la personne morale mentionnée à la première phrase du présent alinéa n'a pas déposé dans le délai légal les déclarations qu'il était tenu de souscrire et soit n'a pas fait connaître son activité à l'organisme mentionné au deuxième alinéa de l'article L. 123-33 du code de commerce, soit s'est livré à une activité illicite.\nPar exception au premier alinéa du présent article, le droit de reprise de l'administration s'exerce jusqu'à la fin de la dixième année qui suit celle au titre de laquelle l'imposition est due lorsqu'une personne physique se prévaut d'une fausse domiciliation fiscale à l'étranger.\nLe droit de reprise mentionné aux deuxième et troisième alinéas du présent article ne s'applique qu'aux seules catégories de revenus que le contribuable n'a pas fait figurer dans une quelconque des déclarations qu'il a déposées dans le délai légal. Il ne s'applique pas lorsque des revenus ou plus-values ont été déclarés dans une catégorie autre que celle dans laquelle ils doivent être imposés.\nLe droit de reprise de l'administration s'exerce jusqu'à la fin de la dixième année qui suit celle au titre de laquelle l'imposition est due, lorsque les obligations déclaratives prévues aux articles 123 bis, 209 B, 1649 A , 1649 AA, 1649 AB et 1649 bis C du code général des impôts n'ont pas été respectées. Toutefois, en cas de non-respect de l'obligation déclarative prévue à l'article 1649 A précité, cette extension de délai ne s'applique pas lorsque le contribuable apporte la preuve que le total des soldes créditeurs de ses comptes à l'étranger n'a pas excédé 50 000 € à un moment quelconque de l'année au titre de laquelle la déclaration devait être faite. Le droit de reprise de l'administration concerne les seuls revenus ou bénéfices afférents aux obligations déclaratives qui n'ont pas été respectées.\nLe droit de reprise de l'administration s'exerce jusqu'à la fin de la dixième année qui suit celle au titre de laquelle l'imposition est due, lorsque l'administration a dressé un procès-verbal de flagrance fiscale dans les conditions prévues à l'article L. 16-0 BA, au titre d'une année postérieure.\nSi le déficit d'ensemble ou la moins-value nette à long terme d'ensemble subis par un groupe mentionné à l'article 223 A ou à l'article 223 A bis du code général des impôts sont imputés dans les conditions prévues aux articles 223 C et 223 D dudit code sur le résultat d'ensemble ou la plus-value nette à long terme d'ensemble réalisés au titre de l'un des exercices clos au cours de la période mentionnée au premier alinéa, les résultats et les plus-values ou moins-values nettes à long terme réalisés par les sociétés de ce groupe et qui ont concouru à la détermination de ce déficit ou de cette moins-value peuvent être remis en cause à hauteur du montant du déficit ou de la moins-value ainsi imputés, nonobstant les dispositions prévues au premier alinéa.\nSi le groupe a cessé d'exister, les règles définies au septième alinéa demeurent applicables au déficit ou à la moins-value nette à long terme définis au cinquième alinéa de l'article 223 S du code général des impôts.\nLe retrait de l'un des agréments prévus aux articles 199 undecies B, 199 undecies C, 217 undecies, 217 duodecies, 244 quater I, 244 quater W et 244 quater Y du code général des impôts et la reprise des avantages fiscaux en application du 1 de l'article 1649 nonies A du même code peuvent intervenir jusqu'à la fin de la troisième année qui suit celle de la rupture de l'engagement souscrit en vue d'obtenir l'agrément ou celle du non-respect des conditions auxquelles l'octroi de ce dernier a été subordonné.","note":"Délai de reprise (prescription) de droit commun, sauf délais spéciaux plus longs (activité occulte...)."},{"id":"seed-art-27","matiere":"Droit fiscal","code":"Code général des impôts","numero":"4 B","texte":"1. Sont considérées comme ayant leur domicile fiscal en France au sens de l'article 4 A :\na. Les personnes qui ont en France leur foyer ou le lieu de leur séjour principal ;\nb. Celles qui exercent en France une activité professionnelle, salariée ou non, à moins qu'elles ne justifient que cette activité y est exercée à titre accessoire ;\nLes dirigeants des entreprises dont le siège est situé en France et qui y réalisent un chiffre d'affaires annuel supérieur à 250 millions d'euros sont considérés comme exerçant en France leur activité professionnelle à titre principal, à moins qu'ils ne rapportent la preuve contraire. Pour les entreprises qui contrôlent d'autres entreprises dans les conditions définies à l'article L. 233-16 du code de commerce, le chiffre d'affaires s'entend de la somme de leur chiffre d'affaires et de celui des entreprises qu'elles contrôlent.\nLes dirigeants mentionnés au deuxième alinéa du présent b s'entendent du président du conseil d'administration lorsqu'il assume la direction générale de la société, du directeur général, des directeurs généraux délégués, du président et des membres du directoire, des gérants et des autres dirigeants ayant des fonctions analogues ;\nc. Celles qui ont en France le centre de leurs intérêts économiques.\nLes personnes qui satisfont à l'un au moins des critères fixés aux a à c du présent 1 ne peuvent toutefois pas être considérées comme ayant leur domicile fiscal en France lorsque, par application des conventions internationales relatives aux doubles impositions, elles ne sont pas regardées comme résidentes de France.\n2. Sont également considérés comme ayant leur domicile fiscal en France les agents de l'Etat, des collectivités territoriales et de la fonction publique hospitalière qui exercent leurs fonctions ou sont chargés de mission dans un pays étranger et qui ne sont pas soumis dans ce pays à un impôt personnel sur l'ensemble de leurs revenus.","note":"Critères alternatifs de détermination du domicile fiscal, point de départ de la territorialité de l'IR."},{"id":"seed-art-28","matiere":"Régime général des obligations","code":"Code civil","numero":"1231-1","texte":"Le débiteur est condamné, s'il y a lieu, au paiement de dommages et intérêts soit à raison de l'inexécution de l'obligation, soit à raison du retard dans l'exécution, s'il ne justifie pas que l'exécution a été empêchée par la force majeure.","note":"Fondement de la responsabilité contractuelle de droit commun."},{"id":"seed-art-29","matiere":"Régime général des obligations","code":"Code civil","numero":"1346","texte":"La subrogation a lieu par le seul effet de la loi au profit de celui qui, y ayant un intérêt légitime, paie dès lors que son paiement libère envers le créancier celui sur qui doit peser la charge définitive de tout ou partie de la dette.","note":"Subrogation légale — à distinguer de la subrogation conventionnelle (art. 1346-1)."},{"id":"seed-art-30","matiere":"Régime général des obligations","code":"Code civil","numero":"1327","texte":"Un débiteur peut, avec l'accord du créancier, céder sa dette.\nLa cession doit être constatée par écrit, à peine de nullité.","note":"Consacre explicitement la cession de dette depuis la réforme du droit des obligations de 2016."},{"id":"seed-art-31","matiere":"Régime général des obligations","code":"Code civil","numero":"2224","texte":"Les actions personnelles ou mobilières se prescrivent par cinq ans à compter du jour où le titulaire d'un droit a connu ou aurait dû connaître les faits lui permettant de l'exercer.","note":"Délai de prescription extinctive de droit commun."},{"id":"seed-art-32","matiere":"Régime général des obligations","code":"Code civil","numero":"1216","texte":"Un contractant, le cédant, peut céder sa qualité de partie au contrat à un tiers, le cessionnaire, avec l'accord de son cocontractant, le cédé.\nCet accord peut être donné par avance, notamment dans le contrat conclu entre les futurs cédant et cédé, auquel cas la cession produit effet à l'égard du cédé lorsque le contrat conclu entre le cédant et le cessionnaire lui est notifié ou lorsqu'il en prend acte.\nLa cession doit être constatée par écrit, à peine de nullité.","note":"Consacre la cession de contrat (transmission de la qualité de partie), également issue de la réforme de 2016."}],"fiches":[{"id":"seed-fa-0","titre":"Blanco","juridiction":"Tribunal des conflits","date":"1873-02-08","matiere":"Droit public des affaires","faits":"Une fillette est blessée par un wagonnet appartenant à une manufacture de tabac, service exploité par l'État.","procedure":"Le Tribunal des conflits est saisi pour déterminer l'ordre juridictionnel compétent, judiciaire ou administratif.","probleme":"La responsabilité de l'État du fait des services publics relève-t-elle des règles de droit commun applicables entre particuliers ?","solution":"Non : la responsabilité de la puissance publique n'est ni générale ni absolue, elle a ses règles propres qui varient selon les besoins du service et la nécessité de concilier les droits de l'État avec les droits privés ; le juge administratif est compétent.","portee":"Arrêt fondateur du droit administratif français : il consacre son autonomie par rapport au droit civil et pose les bases de la responsabilité administrative."},{"id":"seed-fa-1","titre":"Société commerciale de l'Ouest africain (\"Bac d'Eloka\")","juridiction":"Autre","date":"1921-01-22","matiere":"Droit public des affaires","faits":"Un usager est victime d'un accident lors de la traversée d'une lagune par un bac exploité par une colonie.","procedure":"Question de compétence juridictionnelle portée devant le Tribunal des conflits.","probleme":"Le service d'un bac, exploité dans les mêmes conditions qu'une entreprise privée, relève-t-il du droit administratif ?","solution":"Non : lorsqu'une personne publique gère un service dans les mêmes conditions qu'un industriel ordinaire, ce service est un service public industriel et commercial (SPIC) relevant du droit privé et du juge judiciaire.","portee":"Consacre la distinction SPA/SPIC, fondamentale pour déterminer le régime juridique applicable aux activités publiques à caractère économique."},{"id":"seed-fa-2","titre":"Époux Bertin","juridiction":"Conseil d'État","date":"1956-04-20","matiere":"Droit public des affaires","faits":"Un contrat verbal confie à des particuliers la nourriture de réfugiés en 1944, dans le cadre d'une mission de service public confiée par l'État.","procedure":"Litige né de l'exécution du contrat ; question de la juridiction compétente.","probleme":"Un contrat ayant pour objet l'exécution même du service public est-il, de ce seul fait, un contrat administratif ?","solution":"Oui : un contrat par lequel un particulier est associé directement à l'exécution même du service public est un contrat administratif, sans qu'il soit besoin de rechercher l'existence de clauses exorbitantes.","portee":"Consacre un critère matériel alternatif (l'objet du contrat) de qualification du contrat administratif, à côté du critère des clauses exorbitantes."},{"id":"seed-fa-3","titre":"Association du personnel relevant des établissements pour inadaptés (APREI)","juridiction":"Conseil d'État","date":"2007-02-22","matiere":"Droit public des affaires","faits":"Une personne privée exerce une activité d'intérêt général sans disposer de prérogatives de puissance publique.","procedure":"Pourvoi devant le Conseil d'État sur la qualification de l'activité.","probleme":"Une personne privée peut-elle être regardée comme chargée d'une mission de service public en l'absence de prérogatives de puissance publique ?","solution":"Oui, sous réserve d'un faisceau d'indices : conditions de création, d'organisation et de fonctionnement, obligations imposées, mesures de contrôle par l'administration, prérogatives éventuelles.","portee":"Assouplit les critères \"Narcy\" (1963) en admettant la reconnaissance d'un service public confié à une personne privée même sans prérogative de puissance publique."},{"id":"seed-fa-4","titre":"Motte","juridiction":"Cour de cassation","date":"1946-06-04","matiere":"Droit des sociétés","faits":"Un litige oppose les organes d'une société commerciale sur la répartition de leurs pouvoirs respectifs.","procedure":"Pourvoi en cassation sur la portée des décisions de l'assemblée générale.","probleme":"L'assemblée générale des actionnaires peut-elle empiéter sur les attributions du conseil d'administration ?","solution":"Non : chaque organe social dispose de compétences qui lui sont propres et exclusives ; l'assemblée ne peut se substituer au conseil d'administration dans l'exercice de ses attributions légales.","portee":"Arrêt fondateur du principe de la hiérarchie et de la spécialisation des pouvoirs entre organes sociaux, toujours invoqué en droit des sociétés."},{"id":"seed-fa-5","titre":"Comité d'établissement de Saint-Chamond","juridiction":"Cour de cassation","date":"1954-01-28","matiere":"Droit des sociétés","faits":"Un comité d'établissement, groupement non expressément doté de la personnalité morale par un texte, agit en justice.","procedure":"Pourvoi sur la capacité juridique du comité à agir.","probleme":"Un groupement peut-il se voir reconnaître la personnalité morale en l'absence de texte le prévoyant expressément ?","solution":"Oui : la personnalité civile n'est pas une création de la loi, elle appartient en principe à tout groupement pourvu d'une possibilité d'expression collective pour la défense d'intérêts licites, dignes d'être juridiquement protégés.","portee":"Consacre une conception \"réaliste\" de la personnalité morale, essentielle pour comprendre la nature juridique de la société au-delà du seul formalisme de l'immatriculation."},{"id":"seed-fa-6","titre":"Société Générale (lien de subordination)","juridiction":"Cour de cassation","date":"1996-11-13","matiere":"Droit du travail","faits":"Un litige porte sur la qualification d'une relation contractuelle en contrat de travail.","procedure":"Pourvoi en cassation (chambre sociale) sur les critères du contrat de travail.","probleme":"Quel est le critère déterminant pour qualifier une relation contractuelle de contrat de travail ?","solution":"Le lien de subordination juridique, caractérisé par l'exécution d'un travail sous l'autorité d'un employeur qui a le pouvoir de donner des ordres et directives, d'en contrôler l'exécution et de sanctionner les manquements.","portee":"Fixe la définition de référence du lien de subordination, critère central de qualification du contrat de travail encore appliqué aujourd'hui."},{"id":"seed-fa-7","titre":"Jurisprudence constante — définition de la faute grave","juridiction":"Cour de cassation","date":"","matiere":"Droit du travail","faits":"Divers litiges relatifs à la qualification d'une faute commise par un salarié comme justifiant une rupture immédiate du contrat.","procedure":"Contentieux récurrent devant la chambre sociale de la Cour de cassation.","probleme":"À quelles conditions une faute du salarié peut-elle priver celui-ci du préavis et de l'indemnité de licenciement ?","solution":"La faute grave est celle qui rend impossible le maintien du salarié dans l'entreprise pendant la durée du préavis, même limitée dans le temps.","portee":"Formule désormais constante, à distinguer de la faute lourde qui suppose en plus une intention de nuire à l'employeur."},{"id":"seed-fa-8","titre":"Benjamin","juridiction":"Conseil d'État","date":"1933-05-19","matiere":"Libertés fondamentales","faits":"Un maire interdit une réunion publique par crainte de troubles à l'ordre public.","procedure":"Recours pour excès de pouvoir contre l'arrêté d'interdiction.","probleme":"Dans quelle mesure une autorité de police peut-elle restreindre une liberté publique au nom de la prévention de troubles éventuels ?","solution":"L'interdiction n'est légale que si elle est nécessaire, adaptée et proportionnée au risque de trouble à l'ordre public ; de simples risques éventuels ne suffisent pas si des mesures moins contraignantes sont possibles.","portee":"Arrêt fondateur du contrôle maximum (proportionnalité) exercé par le juge administratif sur les mesures de police restreignant les libertés publiques."},{"id":"seed-fa-9","titre":"Commune de Morsang-sur-Orge","juridiction":"Conseil d'État","date":"1995-10-27","matiere":"Libertés fondamentales","faits":"Un maire interdit un spectacle de \"lancer de nains\" sur le territoire de sa commune.","procedure":"Recours contre l'arrêté d'interdiction, en l'absence de circonstances locales particulières de trouble à l'ordre public.","probleme":"Le respect de la dignité de la personne humaine peut-il fonder, à lui seul, une mesure de police restreignant une liberté ?","solution":"Oui : le respect de la dignité de la personne humaine est une composante de l'ordre public, permettant à l'autorité de police d'interdire une attraction qui y porte atteinte, même en l'absence de circonstances locales particulières.","portee":"Consacre la dignité de la personne humaine comme composante autonome de l'ordre public, décision majeure et discutée en doctrine."},{"id":"seed-fa-10","titre":"QPC garde à vue","juridiction":"Conseil constitutionnel","date":"2010-07-30","matiere":"Procédure pénale","faits":"Le régime de droit commun de la garde à vue ne garantit pas l'assistance effective d'un avocat pendant les auditions.","procedure":"Questions prioritaires de constitutionnalité transmises au Conseil constitutionnel.","probleme":"Le régime de la garde à vue de droit commun est-il conforme aux droits et libertés garantis par la Constitution, notamment aux droits de la défense ?","solution":"Non : en l'état, les dispositions ne permettaient pas d'assurer un exercice effectif des droits de la défense, dont l'assistance d'un avocat lors des auditions ; abrogation différée pour laisser le temps d'une réforme.","portee":"Décision majeure ayant entraîné la réforme de 2011 sur la garde à vue (présence effective de l'avocat, notification des droits...)."},{"id":"seed-fa-11","titre":"Sté Janfin (abus de droit fiscal)","juridiction":"Conseil d'État","date":"2006-09-27","matiere":"Droit fiscal","faits":"Une société réalise un montage juridique dans le seul but d'obtenir un avantage fiscal, en dehors du champ littéral de l'article L64 LPF alors en vigueur.","procedure":"Contentieux fiscal devant le Conseil d'État.","probleme":"L'administration peut-elle sanctionner un montage recherchant un but exclusivement fiscal même hors du champ strict de la procédure d'abus de droit prévue par les textes ?","solution":"Oui : le Conseil d'État consacre une théorie prétorienne de la fraude à la loi fiscale, permettant d'écarter les montages artificiels recherchant le bénéfice d'une application littérale des textes contraire à l'intention de leurs auteurs.","portee":"Contribue à la construction de la théorie de l'abus de droit fiscal, avant sa codification étendue à l'article L64 du LPF."},{"id":"seed-fa-12","titre":"Mercier","juridiction":"Cour de cassation","date":"1936-05-20","matiere":"Régime général des obligations","faits":"Un patient invoque la responsabilité d'un médecin après l'échec d'un traitement.","procedure":"Pourvoi en cassation sur le fondement de la responsabilité applicable à la relation médecin-patient.","probleme":"La responsabilité du médecin envers son patient est-elle de nature contractuelle ou délictuelle, et de quelle intensité est son obligation ?","solution":"Il se forme entre le médecin et son patient un véritable contrat, dont découle pour le praticien l'obligation de donner des soins consciencieux, attentifs et conformes aux données de la science — une obligation de moyens, non de résultat.","portee":"Arrêt fondateur de la distinction obligation de moyens / obligation de résultat, toujours structurante en droit des obligations."},{"id":"seed-fa-13","titre":"Myr'Ho c. Boot Shop (\"Bootshop\")","juridiction":"Cour de cassation","date":"2006-10-06","matiere":"Régime général des obligations","faits":"Un locataire subit un préjudice résultant de l'inexécution d'un contrat conclu entre son bailleur et un tiers.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation.","probleme":"Un tiers à un contrat peut-il invoquer un manquement contractuel sur le fondement de la responsabilité délictuelle ?","solution":"Oui : le tiers à un contrat peut invoquer, sur le fondement de la responsabilité délictuelle, un manquement contractuel dès lors que ce manquement lui a causé un dommage, sans avoir à démontrer une faute délictuelle distincte.","portee":"Arrêt majeur sur l'opposabilité du contrat aux tiers, très discuté, qui facilite l'action des tiers victimes d'une inexécution contractuelle."}],"memo":[{"id":"seed-fc-0","matiere":"Droit public des affaires","recto":"Qu'est-ce que le droit public des affaires ?","verso":"Branche du droit public qui régit l'intervention des personnes publiques dans la vie économique : réglementation économique, contrats publics, entreprises publiques, aides d'État."},{"id":"seed-fc-1","matiere":"Droit public des affaires","recto":"Définition du service public","verso":"Activité d'intérêt général assurée ou assumée par une personne publique, soumise à un régime juridique spécifique (principes de continuité, d'égalité et de mutabilité/adaptabilité)."},{"id":"seed-fc-2","matiere":"Droit public des affaires","recto":"Différence entre SPA et SPIC ?","verso":"Le SPA (service public administratif) est soumis au droit administratif. Le SPIC (service public industriel et commercial) est soumis principalement au droit privé pour ses usagers et son personnel, sauf le dirigeant et le comptable public."},{"id":"seed-fc-3","matiere":"Droit public des affaires","recto":"Critères \"Narcy\" de la mission de service public confiée à une personne privée","verso":"Mission d'intérêt général, contrôle exercé par l'administration, prérogatives de puissance publique — critères assouplis ensuite par l'arrêt APREI (2007) en faisceau d'indices."},{"id":"seed-fc-4","matiere":"Droit public des affaires","recto":"Qu'est-ce qu'un marché public ?","verso":"Contrat conclu à titre onéreux entre un acheteur public et un opérateur économique, pour répondre à ses besoins en matière de travaux, de fournitures ou de services."},{"id":"seed-fc-5","matiere":"Droit public des affaires","recto":"Qu'est-ce qu'une délégation de service public / concession ?","verso":"Contrat par lequel une personne publique confie la gestion d'un service public à un délégataire dont la rémunération est substantiellement liée aux résultats de l'exploitation."},{"id":"seed-fc-6","matiere":"Droit public des affaires","recto":"Principe de liberté du commerce et de l'industrie","verso":"Principe selon lequel toute personne est libre d'exercer l'activité économique de son choix ; il encadre et limite l'intervention des personnes publiques dans l'économie."},{"id":"seed-fc-7","matiere":"Droit public des affaires","recto":"Qu'est-ce qu'une société d'économie mixte (SEM) ?","verso":"Société commerciale dont le capital est détenu conjointement par des personnes publiques (majoritaires) et des personnes privées."},{"id":"seed-fc-8","matiere":"Droit public des affaires","recto":"Comment identifier un contrat administratif ?","verso":"Critère organique (une personne publique est partie au contrat) combiné à un critère matériel : clauses exorbitantes du droit commun, ou objet lié à l'exécution même du service public."},{"id":"seed-fc-9","matiere":"Droit public des affaires","recto":"Qu'est-ce qu'une aide d'État (droit de l'Union) ?","verso":"Avantage sélectif accordé par une autorité publique, faussant la concurrence et affectant les échanges entre États membres (art. 107 TFUE) ; interdite en principe, sauf dérogations."},{"id":"seed-fc-10","matiere":"Droit des sociétés","recto":"Définition légale de la société (art. 1832 C. civ.)","verso":"Contrat par lequel deux ou plusieurs personnes conviennent d'affecter à une entreprise commune des biens ou leur industrie en vue de partager le bénéfice ou de profiter de l'économie qui pourra en résulter, et de contribuer aux pertes."},{"id":"seed-fc-11","matiere":"Droit des sociétés","recto":"Qu'est-ce que l'affectio societatis ?","verso":"Volonté des associés de collaborer ensemble, sur un pied d'égalité, à la réussite de l'entreprise commune ; élément constitutif du contrat de société."},{"id":"seed-fc-12","matiere":"Droit des sociétés","recto":"Effet de l'immatriculation au RCS ?","verso":"La société acquiert la personnalité morale : patrimoine propre, capacité d'agir en justice, nom, siège et nationalité distincts de ceux des associés."},{"id":"seed-fc-13","matiere":"Droit des sociétés","recto":"Les trois types d'apports en société","verso":"Apport en numéraire (somme d'argent), en nature (bien), en industrie (travail, savoir-faire) ; seuls les deux premiers forment le capital social."},{"id":"seed-fc-14","matiere":"Droit des sociétés","recto":"Différence SARL / SAS ?","verso":"La SARL a un cadre légal rigide (gérant, parts sociales peu cessibles). La SAS offre une grande liberté statutaire (président, organisation des actions largement libre)."},{"id":"seed-fc-15","matiere":"Droit des sociétés","recto":"Qu'est-ce que l'abus de majorité ?","verso":"Décision prise contrairement à l'intérêt général de la société et dans l'unique dessein de favoriser les associés majoritaires au détriment des minoritaires."},{"id":"seed-fc-16","matiere":"Droit des sociétés","recto":"Qu'est-ce que l'abus de biens sociaux ?","verso":"Infraction pénale : le fait, pour un dirigeant, d'user des biens ou du crédit de la société de manière contraire à l'intérêt social, à des fins personnelles."},{"id":"seed-fc-17","matiere":"Droit des sociétés","recto":"Effet de la nullité d'une société ?","verso":"En principe pas d'effet rétroactif entre associés ni à l'égard des tiers ; les causes de nullité sont limitativement encadrées par la loi (régime protecteur)."},{"id":"seed-fc-18","matiere":"Droit des sociétés","recto":"Qu'est-ce qu'une action \"ut singuli\" ?","verso":"Action en responsabilité exercée par un ou plusieurs associés au nom et pour le compte de la société contre ses dirigeants, en cas de préjudice social."},{"id":"seed-fc-19","matiere":"Droit des sociétés","recto":"Rôle du commissaire aux comptes ?","verso":"Contrôler la régularité et la sincérité des comptes sociaux et certifier les comptes annuels, dans les sociétés dépassant certains seuils légaux."},{"id":"seed-fc-20","matiere":"Droit du travail","recto":"Définition du contrat de travail","verso":"Convention par laquelle une personne s'engage à travailler pour le compte et sous la subordination d'une autre, moyennant rémunération."},{"id":"seed-fc-21","matiere":"Droit du travail","recto":"Critère du lien de subordination","verso":"Pouvoir de l'employeur de donner des ordres et directives, d'en contrôler l'exécution, et de sanctionner les manquements du salarié (Cass. soc., Société Générale, 1996)."},{"id":"seed-fc-22","matiere":"Droit du travail","recto":"Différence CDI / CDD ?","verso":"Le CDI est le contrat de droit commun, sans terme fixé. Le CDD est un contrat d'exception, à terme précis, réservé aux cas prévus par la loi (remplacement, surcroît temporaire d'activité...)."},{"id":"seed-fc-23","matiere":"Droit du travail","recto":"Qu'est-ce que la période d'essai ?","verso":"Période initiale du contrat permettant à chaque partie d'évaluer si la relation convient, durant laquelle la rupture est facilitée (en principe sans motif ni indemnité)."},{"id":"seed-fc-24","matiere":"Droit du travail","recto":"Qu'est-ce qu'une cause réelle et sérieuse de licenciement ?","verso":"Motif objectif, existant et vérifiable, suffisamment grave pour justifier la rupture du contrat, apprécié souverainement par le juge en cas de litige."},{"id":"seed-fc-25","matiere":"Droit du travail","recto":"Différence faute grave / faute lourde ?","verso":"La faute grave rend impossible le maintien du salarié dans l'entreprise (prive de préavis et d'indemnité de licenciement). La faute lourde suppose en plus une intention de nuire à l'employeur."},{"id":"seed-fc-26","matiere":"Droit du travail","recto":"Qu'est-ce qu'une convention collective ?","verso":"Accord négocié entre organisations syndicales et patronales fixant les conditions de travail et garanties sociales applicables à une branche ou une entreprise."},{"id":"seed-fc-27","matiere":"Droit du travail","recto":"Qu'est-ce que le CSE ?","verso":"Comité social et économique : instance unique de représentation du personnel, issue de la fusion des anciennes instances (délégués du personnel, comité d'entreprise, CHSCT)."},{"id":"seed-fc-28","matiere":"Droit du travail","recto":"Durée légale du travail effectif ?","verso":"35 heures par semaine (durée légale, non maximale) ; au-delà, les heures sont en principe majorées (heures supplémentaires)."},{"id":"seed-fc-29","matiere":"Droit du travail","recto":"Qu'est-ce que le pouvoir de direction de l'employeur ?","verso":"Prérogative permettant à l'employeur d'organiser, diriger et contrôler l'activité de l'entreprise et de ses salariés, dans le respect de la loi et des libertés individuelles."},{"id":"seed-fc-30","matiere":"Libertés fondamentales","recto":"Qu'est-ce que le bloc de constitutionnalité ?","verso":"Ensemble des normes de valeur constitutionnelle utilisées par le Conseil constitutionnel : Constitution de 1958, préambule de 1946, DDHC de 1789, Charte de l'environnement, PFRLR."},{"id":"seed-fc-31","matiere":"Libertés fondamentales","recto":"Qu'est-ce que la QPC ?","verso":"Question prioritaire de constitutionnalité : mécanisme permettant à tout justiciable de contester, à l'occasion d'une instance, la conformité d'une disposition législative aux droits et libertés garantis par la Constitution."},{"id":"seed-fc-32","matiere":"Libertés fondamentales","recto":"Apport de l'arrêt CE, Commune de Morsang-sur-Orge (1995)","verso":"Le respect de la dignité de la personne humaine est une composante de l'ordre public, permettant à une autorité de police d'interdire une activité même sans circonstances locales particulières."},{"id":"seed-fc-33","matiere":"Libertés fondamentales","recto":"Apport de l'arrêt CE, Benjamin (1933)","verso":"Contrôle maximum (proportionnalité) du juge administratif sur les mesures de police restreignant une liberté publique : la mesure doit être nécessaire, adaptée et proportionnée."},{"id":"seed-fc-34","matiere":"Libertés fondamentales","recto":"Qu'est-ce que le référé-liberté ?","verso":"Procédure d'urgence permettant au juge administratif d'ordonner, en principe sous 48 heures, toute mesure nécessaire à la sauvegarde d'une liberté fondamentale gravement et manifestement illégalement atteinte."},{"id":"seed-fc-35","matiere":"Libertés fondamentales","recto":"Qu'est-ce que le contrôle de conventionnalité ?","verso":"Contrôle par lequel tout juge (judiciaire ou administratif) écarte l'application d'une loi contraire à un traité international (ex. CESDH) — à la différence du contrôle de constitutionnalité, réservé au Conseil constitutionnel."},{"id":"seed-fc-36","matiere":"Libertés fondamentales","recto":"Article 8 de la CESDH","verso":"Droit au respect de la vie privée et familiale, du domicile et de la correspondance, sous réserve d'ingérences prévues par la loi et nécessaires dans une société démocratique."},{"id":"seed-fc-37","matiere":"Libertés fondamentales","recto":"Liberté publique vs droit fondamental ?","verso":"\"Liberté publique\" est une notion historiquement liée à la loi et au juge administratif français. \"Droit fondamental\" est une notion plus large, d'origine constitutionnelle et européenne, incluant aussi les droits sociaux."},{"id":"seed-fc-38","matiere":"Libertés fondamentales","recto":"Principe d'égalité devant la loi","verso":"La loi doit traiter de manière identique les personnes placées dans une situation identique, sans empêcher un traitement différencié entre situations différentes ou pour un motif d'intérêt général."},{"id":"seed-fc-39","matiere":"Libertés fondamentales","recto":"Théorie des circonstances exceptionnelles","verso":"Théorie jurisprudentielle permettant à l'administration, en période de crise grave, d'étendre ses pouvoirs au-delà du cadre légal ordinaire, sous le contrôle du juge."},{"id":"seed-fc-40","matiere":"Procédure pénale","recto":"Qu'est-ce que la présomption d'innocence ?","verso":"Toute personne suspectée ou poursuivie est présumée innocente tant que sa culpabilité n'a pas été légalement établie (art. préliminaire CPP, art. 9 DDHC)."},{"id":"seed-fc-41","matiere":"Procédure pénale","recto":"Qu'est-ce que la garde à vue ?","verso":"Mesure de contrainte par laquelle une personne soupçonnée est retenue dans les locaux d'un service d'enquête, sous le contrôle d'un magistrat, pour les nécessités de l'enquête."},{"id":"seed-fc-42","matiere":"Procédure pénale","recto":"Qu'est-ce que la mise en examen ?","verso":"Décision du juge d'instruction plaçant sous statut procédural protecteur (accès au dossier, avocat...) une personne contre laquelle existent des indices graves ou concordants."},{"id":"seed-fc-43","matiere":"Procédure pénale","recto":"Différence contrôle judiciaire / détention provisoire ?","verso":"Le contrôle judiciaire impose des obligations à une personne mise en examen laissée libre. La détention provisoire est une mesure exceptionnelle de privation de liberté avant jugement, décidée par le JLD."},{"id":"seed-fc-44","matiere":"Procédure pénale","recto":"Qu'est-ce que l'action publique ?","verso":"Action exercée au nom de la société par le ministère public (procureur) pour l'application de la loi pénale à l'auteur d'une infraction."},{"id":"seed-fc-45","matiere":"Procédure pénale","recto":"Rôle de la chambre de l'instruction ?","verso":"Juridiction d'appel des décisions du juge d'instruction et du JLD ; contrôle aussi la régularité de la procédure (nullités)."},{"id":"seed-fc-46","matiere":"Procédure pénale","recto":"Qu'est-ce qu'une nullité de procédure ?","verso":"Sanction d'un acte de procédure accompli en violation d'une formalité substantielle, entraînant son annulation et celle des actes qui en découlent."},{"id":"seed-fc-47","matiere":"Procédure pénale","recto":"Délais de prescription de l'action publique ?","verso":"20 ans pour les crimes, 6 ans pour les délits, 1 an pour les contraventions, à compter du jour de l'infraction (sauf règles particulières)."},{"id":"seed-fc-48","matiere":"Procédure pénale","recto":"Qu'est-ce que la comparution immédiate ?","verso":"Procédure de jugement rapide d'une personne majeure pour un délit, lorsque les charges sont suffisantes et l'affaire en état d'être jugée."},{"id":"seed-fc-49","matiere":"Procédure pénale","recto":"Rôle du juge des libertés et de la détention (JLD) ?","verso":"Magistrat du siège compétent pour statuer sur les mesures les plus attentatoires à la liberté individuelle : détention provisoire, certaines perquisitions, prolongation de garde à vue."},{"id":"seed-fc-50","matiere":"Droit fiscal","recto":"Définition de l'impôt","verso":"Prestation pécuniaire requise des contribuables par voie d'autorité, à titre définitif, sans contrepartie directe, en vue de la couverture des charges publiques."},{"id":"seed-fc-51","matiere":"Droit fiscal","recto":"Principe de territorialité de l'IS","verso":"Seuls les bénéfices réalisés par des entreprises exploitées en France sont en principe soumis à l'impôt sur les sociétés français, indépendamment de la nationalité de la société."},{"id":"seed-fc-52","matiere":"Droit fiscal","recto":"Qu'est-ce que l'abus de droit fiscal (art. L64 LPF) ?","verso":"Procédure permettant à l'administration d'écarter des actes fictifs, ou recherchant par une application littérale des textes un but exclusivement fiscal contraire à l'intention de leurs auteurs."},{"id":"seed-fc-53","matiere":"Droit fiscal","recto":"Évasion fiscale vs fraude fiscale ?","verso":"L'évasion fiscale utilise des montages légaux pour minimiser l'impôt (avec risque de requalification en abus de droit). La fraude fiscale est une violation intentionnelle et pénalement sanctionnée de la loi fiscale."},{"id":"seed-fc-54","matiere":"Droit fiscal","recto":"Qu'est-ce que l'acte anormal de gestion ?","verso":"Acte contraire à l'intérêt de l'entreprise, l'exposant à une charge ou la privant d'une recette sans contrepartie, permettant à l'administration de rectifier le résultat imposable."},{"id":"seed-fc-55","matiere":"Droit fiscal","recto":"Les trois grandes catégories d'impôts","verso":"Impôts sur le revenu (IR, IS), impôts sur la dépense (TVA), impôts sur le capital/patrimoine (droits de mutation, IFI)."},{"id":"seed-fc-56","matiere":"Droit fiscal","recto":"Qu'est-ce que la taxation d'office ?","verso":"Procédure permettant à l'administration d'évaluer unilatéralement les bases d'imposition d'un contribuable défaillant, en renversant la charge de la preuve."},{"id":"seed-fc-57","matiere":"Droit fiscal","recto":"Délai de reprise de droit commun","verso":"L'administration peut en principe exercer son droit de reprise jusqu'à la fin de la 3e année suivant celle au titre de laquelle l'imposition est due."},{"id":"seed-fc-58","matiere":"Droit fiscal","recto":"Qu'est-ce que le rescrit fiscal ?","verso":"Prise de position formelle de l'administration sur l'application d'un texte fiscal à une situation de fait précise, qui lui devient opposable si la présentation était exacte et complète."},{"id":"seed-fc-59","matiere":"Droit fiscal","recto":"Principe de légalité de l'impôt","verso":"La loi fixe les règles concernant l'assiette, le taux et les modalités de recouvrement des impositions de toute nature (art. 34 Constitution)."},{"id":"seed-fc-60","matiere":"Régime général des obligations","recto":"Définition de l'obligation","verso":"Lien de droit unissant un créancier et un débiteur, en vertu duquel ce dernier est tenu envers le premier d'une prestation (donner, faire ou ne pas faire)."},{"id":"seed-fc-61","matiere":"Régime général des obligations","recto":"Obligation de moyens vs obligation de résultat ?","verso":"Dans l'obligation de moyens, le débiteur s'engage à mettre en œuvre tous les moyens raisonnables (faute à prouver par le créancier). Dans l'obligation de résultat, sa non-atteinte suffit à établir la faute."},{"id":"seed-fc-62","matiere":"Régime général des obligations","recto":"Qu'est-ce que la solidarité entre débiteurs ?","verso":"Modalité permettant au créancier d'exiger de l'un quelconque des codébiteurs solidaires le paiement de la totalité de la dette, à charge pour lui de se retourner contre les autres."},{"id":"seed-fc-63","matiere":"Régime général des obligations","recto":"Qu'est-ce que la cession de créance ?","verso":"Convention par laquelle le créancier cédant transmet sa créance à un tiers cessionnaire ; opposable au débiteur cédé dès qu'il en est informé ou y intervient."},{"id":"seed-fc-64","matiere":"Régime général des obligations","recto":"Qu'est-ce que la novation ?","verso":"Opération qui éteint une obligation en la remplaçant par une nouvelle (changement de créancier, de débiteur, ou d'objet)."},{"id":"seed-fc-65","matiere":"Régime général des obligations","recto":"Qu'est-ce que la subrogation personnelle ?","verso":"Mécanisme par lequel un tiers qui paie la dette d'autrui est substitué dans les droits du créancier payé contre le débiteur."},{"id":"seed-fc-66","matiere":"Régime général des obligations","recto":"Qu'est-ce que la compensation ?","verso":"Mode d'extinction simultanée de deux dettes réciproques, liquides et exigibles, entre les mêmes personnes, à hauteur de la plus faible des deux."},{"id":"seed-fc-67","matiere":"Régime général des obligations","recto":"Qu'est-ce que la délégation ?","verso":"Opération par laquelle une personne (le délégant) obtient d'une autre (le délégué) qu'elle s'engage envers un tiers (le délégataire), qui accepte cette obligation nouvelle."},{"id":"seed-fc-68","matiere":"Régime général des obligations","recto":"Délai de prescription extinctive de droit commun","verso":"Cinq ans à compter du jour où le titulaire d'un droit a connu ou aurait dû connaître les faits lui permettant de l'exercer (art. 2224 C. civ.)."},{"id":"seed-fc-69","matiere":"Régime général des obligations","recto":"Qu'est-ce que la cession de dette ?","verso":"Convention par laquelle un débiteur cédant transmet sa dette à un tiers cessionnaire, avec l'accord du créancier, qui peut ou non libérer le débiteur originaire."},{"id":"seed-fc-l1-entree-vigueur","matiere":"Introduction au droit","recto":"Quand une loi publiée au Journal officiel entre-t-elle en vigueur ?","verso":"À la date qu'elle fixe ou, à défaut, le lendemain de sa publication. Les dispositions qui exigent des mesures d'application n'entrent en vigueur qu'avec ces mesures (art. 1er C. civ.)."},{"id":"seed-fc-l1-non-retroactivite","matiere":"Introduction au droit","recto":"La loi ne dispose que pour l'avenir ; elle n'a point d'effet rétroactif.","verso":"Art. 2 du Code civil : le principe de non-rétroactivité de la loi."},{"id":"seed-fc-l1-deni-justice","matiere":"Introduction au droit","recto":"Un juge peut-il refuser de trancher un litige parce que la loi est muette ou obscure ?","verso":"Non : il commettrait un déni de justice (art. 4 C. civ.). Il doit interpréter la loi et trancher."},{"id":"seed-fc-l1-arrets-reglement","matiere":"Introduction au droit","recto":"Que signifie l'interdiction des « arrêts de règlement » ?","verso":"Le juge ne peut pas statuer par voie de disposition générale et réglementaire : sa décision ne vaut que pour l'affaire qu'il juge (art. 5 C. civ.)."},{"id":"seed-fc-l1-ordre-public","matiere":"Introduction au droit","recto":"On ne peut déroger, par des conventions particulières, aux lois qui intéressent l'ordre public et les bonnes mœurs.","verso":"Art. 6 du Code civil."},{"id":"seed-fc-l1-traites-lois","matiere":"Introduction au droit","recto":"Quelle autorité ont les traités régulièrement ratifiés par rapport aux lois ?","verso":"Une autorité supérieure à celle des lois, dès leur publication, sous réserve de leur application par l'autre partie (art. 55 de la Constitution). Le juge judiciaire en a tiré les conséquences avec l'arrêt Jacques Vabre (1975), le Conseil d'État avec l'arrêt Nicolo (1989)."},{"id":"seed-fc-l1-vie-privee","matiere":"Introduction au droit","recto":"Chacun a droit au respect de sa vie privée.","verso":"Art. 9 du Code civil ; le juge peut ordonner toute mesure pour faire cesser une atteinte à l'intimité de la vie privée."},{"id":"seed-fc-l1-corps-humain","matiere":"Introduction au droit","recto":"Chacun a droit au respect de son corps. Le corps humain est inviolable. Le corps humain, ses éléments et ses produits ne peuvent faire l'objet d'un droit patrimonial.","verso":"Art. 16-1 du Code civil."},{"id":"seed-fc-l1-infans-conceptus","matiere":"Introduction au droit","recto":"Un enfant simplement conçu au décès de son père peut-il hériter de lui ?","verso":"Oui, s'il naît viable : pour succéder, il faut exister à l'ouverture de la succession ou, ayant déjà été conçu, naître viable (art. 725 C. civ.). C'est une application de l'adage « infans conceptus »."},{"id":"seed-fc-l1-majorite","matiere":"Introduction au droit","recto":"La majorité est fixée à dix-huit ans accomplis ; à cet âge, chacun est capable d'exercer les droits dont il a la jouissance.","verso":"Art. 414 du Code civil."},{"id":"seed-fc-l1-curatelle-tutelle","matiere":"Introduction au droit","recto":"Curatelle ou tutelle : quelle différence ?","verso":"En curatelle, la personne agit elle-même mais doit être assistée ou contrôlée dans les actes importants ; en tutelle, elle est représentée de manière continue. Chacune n'est prononcée que si une mesure plus légère (sauvegarde de justice, puis curatelle) ne suffit pas (art. 440 C. civ.)."},{"id":"seed-fc-l1-domicile","matiere":"Introduction au droit","recto":"Où se trouve le domicile d'une personne, au sens du Code civil ?","verso":"Au lieu où elle a son principal établissement (art. 102 C. civ.)."},{"id":"seed-fc-l1-republique","matiere":"Droit constitutionnel","recto":"La France est une République indivisible, laïque, démocratique et sociale.","verso":"Art. 1er de la Constitution du 4 octobre 1958."},{"id":"seed-fc-l1-souverainete","matiere":"Droit constitutionnel","recto":"La souveraineté nationale appartient au peuple qui l'exerce par ses représentants et par la voie du référendum.","verso":"Art. 3 de la Constitution."},{"id":"seed-fc-l1-mandat-president","matiere":"Droit constitutionnel","recto":"Pour combien de temps le Président de la République est-il élu, et combien de mandats peut-il enchaîner ?","verso":"Cinq ans, au suffrage universel direct ; nul ne peut exercer plus de deux mandats consécutifs (art. 6 de la Constitution)."},{"id":"seed-fc-l1-premier-ministre","matiere":"Droit constitutionnel","recto":"Qui nomme le Premier ministre, et comment ses fonctions prennent-elles fin ?","verso":"Le Président de la République le nomme ; il met fin à ses fonctions sur la présentation par le Premier ministre de la démission du Gouvernement (art. 8 de la Constitution)."},{"id":"seed-fc-l1-dissolution","matiere":"Droit constitutionnel","recto":"Le Président peut-il dissoudre l'Assemblée nationale à tout moment ?","verso":"Il peut la dissoudre après avoir consulté le Premier ministre et les présidents des assemblées, mais pas dans l'année qui suit les élections tenues après une dissolution. Les élections ont lieu vingt à quarante jours après la dissolution (art. 12 de la Constitution)."},{"id":"seed-fc-l1-article-16","matiere":"Droit constitutionnel","recto":"À quelles conditions le Président peut-il exercer les pouvoirs exceptionnels de l'article 16 ?","verso":"Il faut une menace grave et immédiate sur les institutions, l'indépendance de la nation, l'intégrité du territoire ou l'exécution des engagements internationaux, et une interruption du fonctionnement régulier des pouvoirs publics constitutionnels. Il consulte le Premier ministre, les présidents des assemblées et le Conseil constitutionnel ; le Parlement se réunit de plein droit."},{"id":"seed-fc-l1-49-3","matiere":"Droit constitutionnel","recto":"Que permet l'article 49, alinéa 3, de la Constitution ?","verso":"Au Premier ministre, après délibération du conseil des ministres, d'engager la responsabilité du Gouvernement sur le vote d'un projet de loi de finances ou de financement de la sécurité sociale : le texte est considéré comme adopté, sauf si une motion de censure déposée dans les vingt-quatre heures est votée. Hors de ces textes, il ne peut le faire que pour un projet ou une proposition de loi par session."},{"id":"seed-fc-l1-conseil-constitutionnel","matiere":"Droit constitutionnel","recto":"Comment le Conseil constitutionnel est-il composé ?","verso":"Neuf membres nommés pour neuf ans, mandat non renouvelable, renouvelés par tiers tous les trois ans : trois par le Président de la République, trois par le président de l'Assemblée nationale, trois par le président du Sénat. Les anciens Présidents de la République en sont membres de droit (art. 56 de la Constitution)."},{"id":"seed-fc-l1-qpc","matiere":"Droit constitutionnel","recto":"Qu'est-ce qu'une question prioritaire de constitutionnalité ?","verso":"Au cours d'un procès, une partie soutient qu'une disposition législative porte atteinte aux droits et libertés que la Constitution garantit. Le Conseil constitutionnel en est saisi sur renvoi du Conseil d'État ou de la Cour de cassation (art. 61-1 de la Constitution)."},{"id":"seed-fc-l1-loi-reglement","matiere":"Droit constitutionnel","recto":"Comment se partagent le domaine de la loi et celui du règlement ?","verso":"L'article 34 énumère les matières dans lesquelles la loi intervient ; toutes les autres matières ont un caractère réglementaire (art. 37 de la Constitution)."},{"id":"seed-fc-l1-preambule","matiere":"Droit constitutionnel","recto":"À quels textes le Préambule de la Constitution de 1958 renvoie-t-il ?","verso":"À la Déclaration des droits de l'homme et du citoyen de 1789, au préambule de la Constitution de 1946 et à la Charte de l'environnement de 2004. Le Conseil constitutionnel a reconnu la valeur constitutionnelle du Préambule dans sa décision « Liberté d'association » (1971)."},{"id":"seed-fc-l1-revision","matiere":"Droit constitutionnel","recto":"Comment révise-t-on la Constitution selon l'article 89 ?","verso":"L'initiative appartient au Président de la République, sur proposition du Premier ministre, et aux parlementaires. Le texte est voté en termes identiques par les deux assemblées, puis approuvé par référendum ; un projet peut aussi être soumis au Congrès, qui doit l'adopter à la majorité des trois cinquièmes des suffrages exprimés. La forme républicaine du Gouvernement ne peut pas être révisée."},{"id":"seed-fc-l1-deux-ordres","matiere":"Institutions juridictionnelles","recto":"Quels sont les deux ordres de juridiction, et qui tranche leurs conflits de compétence ?","verso":"L'ordre judiciaire, avec la Cour de cassation à son sommet, et l'ordre administratif, avec le Conseil d'État. Le Tribunal des conflits tranche les conflits de compétence entre les deux."},{"id":"seed-fc-l1-nom-peuple","matiere":"Institutions juridictionnelles","recto":"Les juridictions judiciaires rendent leurs décisions au nom du peuple français.","verso":"Art. L. 111-1 du Code de l'organisation judiciaire."},{"id":"seed-fc-l1-tribunal-judiciaire","matiere":"Institutions juridictionnelles","recto":"Quelle est la juridiction civile de droit commun en première instance ?","verso":"Le tribunal judiciaire : il connaît de toutes les affaires civiles et commerciales que la loi n'attribue pas à une autre juridiction (art. L. 211-3 COJ). Il a remplacé le tribunal de grande instance et le tribunal d'instance le 1er janvier 2020."},{"id":"seed-fc-l1-cour-appel","matiere":"Institutions juridictionnelles","recto":"Quel est le rôle de la cour d'appel ?","verso":"Elle rejuge les décisions rendues en premier ressort, civiles et pénales, et statue souverainement sur le fond des affaires, en fait comme en droit (art. L. 311-1 COJ)."},{"id":"seed-fc-l1-cassation-fond","matiere":"Institutions juridictionnelles","recto":"La Cour de cassation juge-t-elle les faits ?","verso":"Non : elle statue sur les pourvois contre les décisions rendues en dernier ressort et ne connaît pas du fond des affaires, sauf disposition législative contraire (art. L. 411-2 COJ). Elle contrôle l'application du droit."},{"id":"seed-fc-l1-renvoi","matiere":"Institutions juridictionnelles","recto":"Après une cassation, que devient l'affaire ?","verso":"En principe, elle est renvoyée devant une autre juridiction de même nature, ou devant la même juridiction autrement composée (art. L. 431-4 COJ). La Cour peut casser sans renvoi lorsqu'il n'y a plus rien à juger au fond (art. L. 411-3 COJ)."},{"id":"seed-fc-l1-ordre-administratif","matiere":"Institutions juridictionnelles","recto":"Quelles juridictions administratives jugent en premier ressort, en appel et en cassation ?","verso":"Les tribunaux administratifs en premier ressort (art. L. 211-1 CJA), les cours administratives d'appel en appel (art. L. 211-2 CJA), le Conseil d'État, juridiction administrative suprême, en cassation (art. L. 111-1 CJA)."},{"id":"seed-fc-l1-juridictions-penales","matiere":"Institutions juridictionnelles","recto":"Quelle juridiction pénale juge les contraventions, les délits, les crimes ?","verso":"Le tribunal de police juge les contraventions (art. 521 CPP), le tribunal correctionnel les délits (art. 381 CPP), la cour d'assises les crimes (art. 231 CPP). Les majeurs accusés d'un crime puni de quinze ou vingt ans de réclusion sont jugés en premier ressort par la cour criminelle départementale (art. 380-16 CPP)."},{"id":"seed-fc-l1-prudhommes","matiere":"Institutions juridictionnelles","recto":"Qui juge un différend entre un salarié et son employeur, né du contrat de travail ?","verso":"Le conseil de prud'hommes : il cherche d'abord à concilier les parties, puis juge si la conciliation échoue (art. L. 1411-1 C. trav.)."},{"id":"seed-fc-l1-delai-appel","matiere":"Institutions juridictionnelles","recto":"Quel est le délai de droit commun pour faire appel d'un jugement civil ?","verso":"Un mois en matière contentieuse, quinze jours en matière gracieuse (art. 538 CPC)."},{"id":"seed-fc-l1-delai-pourvoi","matiere":"Institutions juridictionnelles","recto":"Quel est le délai pour former un pourvoi en cassation en matière civile ?","verso":"Deux mois, sauf disposition contraire (art. 612 CPC)."},{"id":"seed-fc-l1-fiche-arret","matiere":"Méthode juridique","recto":"Quelles sont les cinq rubriques d'une fiche d'arrêt ?","verso":"Les faits, la procédure, le problème de droit, la solution et la portée."},{"id":"seed-fc-l1-probleme-droit","matiere":"Méthode juridique","recto":"Comment formuler le problème de droit d'un arrêt ?","verso":"Sous la forme d'une question juridique générale, sans le nom des parties, à laquelle la solution de l'arrêt répond."},{"id":"seed-fc-l1-syllogisme","matiere":"Méthode juridique","recto":"Qu'est-ce qu'un syllogisme juridique ?","verso":"Un raisonnement en trois temps : la majeure (la règle de droit), la mineure (les faits, qualifiés juridiquement) et la conclusion (la règle appliquée à ces faits)."},{"id":"seed-fc-l1-qualification","matiere":"Méthode juridique","recto":"Qu'est-ce que qualifier juridiquement des faits ?","verso":"Les faire entrer dans une catégorie juridique pour savoir quelle règle s'applique. Le juge doit donner ou restituer leur exacte qualification aux faits et actes litigieux (art. 12 CPC)."},{"id":"seed-fc-l1-rejet","matiere":"Méthode juridique","recto":"Que signifie un arrêt de rejet de la Cour de cassation ?","verso":"La Cour écarte le pourvoi : elle estime que la décision attaquée a correctement appliqué le droit, et cette décision est maintenue."},{"id":"seed-fc-l1-cassation","matiere":"Méthode juridique","recto":"Que signifie un arrêt de cassation ?","verso":"La Cour annule, en tout ou en partie, la décision attaquée pour une erreur de droit, et renvoie en principe l'affaire devant une autre juridiction de même nature (art. L. 431-4 COJ)."},{"id":"seed-fc-l1-style-direct","matiere":"Méthode juridique","recto":"Comment la Cour de cassation rédige-t-elle ses arrêts depuis le 1er octobre 2019 ?","verso":"En style direct, sans « attendu que », avec des paragraphes numérotés et trois parties : les faits et la procédure, l'examen des moyens, le dispositif. Les arrêts les plus importants reçoivent une « motivation enrichie », plus développée."},{"id":"seed-fc-l1-plan","matiere":"Méthode juridique","recto":"Quel plan adopter dans une dissertation ou un commentaire juridique ?","verso":"En principe deux parties et deux sous-parties (I, A et B ; II, A et B), annoncées à la fin de l'introduction et rédigées sous forme de titres."},{"id":"seed-fc-l1-principe-espece","matiere":"Méthode juridique","recto":"Arrêt de principe ou arrêt d'espèce : quelle différence ?","verso":"L'arrêt de principe pose une règle générale, appelée à s'appliquer au-delà de l'affaire ; l'arrêt d'espèce donne une solution liée aux faits particuliers du litige."},{"id":"seed-fc-l1-portee","matiere":"Méthode juridique","recto":"Que dit la « portée » dans une fiche d'arrêt ?","verso":"La place de la décision dans le droit : confirme-t-elle, nuance-t-elle ou renverse-t-elle la jurisprudence antérieure, et quelles suites a-t-elle eues (arrêts postérieurs, réforme législative) ?"},{"id":"seed-fc-l2-contrat-definition","matiere":"Droit des contrats","recto":"Qu'est-ce qu'un contrat, selon le Code civil ?","verso":"Un accord de volontés entre deux ou plusieurs personnes destiné à créer, modifier, transmettre ou éteindre des obligations (art. 1101 C. civ.)."},{"id":"seed-fc-l2-force-obligatoire","matiere":"Droit des contrats","recto":"Les contrats légalement formés tiennent lieu de loi à ceux qui les ont faits.","verso":"Art. 1103 du Code civil : la force obligatoire du contrat."},{"id":"seed-fc-l2-bonne-foi","matiere":"Droit des contrats","recto":"Les contrats doivent être négociés, formés et exécutés de bonne foi. Cette disposition est d'ordre public.","verso":"Art. 1104 du Code civil."},{"id":"seed-fc-l2-validite","matiere":"Droit des contrats","recto":"Quelles sont les conditions de validité d'un contrat ?","verso":"Le consentement des parties, leur capacité de contracter, et un contenu licite et certain (art. 1128 C. civ.)."},{"id":"seed-fc-l2-formation","matiere":"Droit des contrats","recto":"Comment un contrat se forme-t-il ?","verso":"Par la rencontre d'une offre et d'une acceptation par lesquelles les parties manifestent leur volonté de s'engager ; cette volonté peut résulter d'une déclaration ou d'un comportement non équivoque (art. 1113 C. civ.)."},{"id":"seed-fc-l2-vices","matiere":"Droit des contrats","recto":"Quels sont les vices du consentement, et quand entraînent-ils la nullité ?","verso":"L'erreur, le dol et la violence, lorsqu'ils sont déterminants : sans eux, la partie n'aurait pas contracté, ou à des conditions substantiellement différentes (art. 1130 C. civ.)."},{"id":"seed-fc-l2-erreur","matiere":"Droit des contrats","recto":"Sur quoi l'erreur doit-elle porter pour entraîner la nullité du contrat ?","verso":"Sur les qualités essentielles de la prestation due ou sur celles du cocontractant ; l'erreur ne doit pas être inexcusable (art. 1132 C. civ.). Exemple : l'authenticité d'une œuvre, dans l'arrêt Poussin."},{"id":"seed-fc-l2-dol","matiere":"Droit des contrats","recto":"Qu'est-ce que le dol ?","verso":"Le fait d'obtenir le consentement de l'autre par des manœuvres ou des mensonges, ou par la dissimulation intentionnelle d'une information qu'on sait déterminante pour lui. Ne pas révéler son estimation de la valeur de la prestation n'est pas un dol (art. 1137 C. civ. ; voir déjà l'arrêt Baldus)."},{"id":"seed-fc-l2-dependance","matiere":"Droit des contrats","recto":"Qu'est-ce que la violence par abus de dépendance ?","verso":"Une partie abuse de l'état de dépendance de son cocontractant pour obtenir de lui un engagement qu'il n'aurait pas souscrit sans cette contrainte, et en tire un avantage manifestement excessif (art. 1143 C. civ.)."},{"id":"seed-fc-l2-obligation-essentielle","matiere":"Droit des contrats","recto":"Que devient une clause qui prive de sa substance l'obligation essentielle du débiteur ?","verso":"Elle est réputée non écrite (art. 1170 C. civ.). La règle vient de l'arrêt Chronopost (1996), à propos d'une clause limitative de responsabilité."},{"id":"seed-fc-l2-imprevision","matiere":"Droit des contrats","recto":"Que permet l'article 1195 du Code civil en cas de changement de circonstances imprévisible ?","verso":"La partie pour qui l'exécution devient excessivement onéreuse peut demander une renégociation, en continuant d'exécuter. En cas d'échec, les parties peuvent convenir de la résolution ou demander au juge d'adapter le contrat ; à défaut d'accord dans un délai raisonnable, le juge peut réviser le contrat ou y mettre fin. Avant 2016, l'arrêt Canal de Craponne refusait toute révision par le juge."},{"id":"seed-fc-l2-inexecution","matiere":"Droit des contrats","recto":"De quelles sanctions dispose le créancier d'une obligation inexécutée ?","verso":"Refuser ou suspendre l'exécution de sa propre obligation, poursuivre l'exécution forcée en nature, obtenir une réduction du prix, provoquer la résolution du contrat, demander réparation. Celles qui sont compatibles se cumulent (art. 1217 C. civ.)."},{"id":"seed-fc-l2-1240","matiere":"Responsabilité civile","recto":"Tout fait quelconque de l'homme, qui cause à autrui un dommage, oblige celui par la faute duquel il est arrivé à le réparer.","verso":"Art. 1240 du Code civil : la responsabilité du fait personnel."},{"id":"seed-fc-l2-1241","matiere":"Responsabilité civile","recto":"Faut-il une faute intentionnelle pour engager sa responsabilité ?","verso":"Non : chacun est responsable du dommage causé non seulement par son fait, mais aussi par sa négligence ou son imprudence (art. 1241 C. civ.)."},{"id":"seed-fc-l2-trois-conditions","matiere":"Responsabilité civile","recto":"Quelles sont les trois conditions de la responsabilité pour faute ?","verso":"Une faute, un dommage, et un lien de causalité entre les deux (art. 1240 C. civ.)."},{"id":"seed-fc-l2-fait-des-choses","matiere":"Responsabilité civile","recto":"D'où vient le principe général de responsabilité du fait des choses ?","verso":"De l'article 1242, alinéa 1er, du Code civil (ancien art. 1384, al. 1er), lu par la jurisprudence comme un principe général : arrêt Teffaine (1896), puis Jand'heur (1930), qui l'étend à toutes les choses et en fait une présomption de responsabilité."},{"id":"seed-fc-l2-garde","matiere":"Responsabilité civile","recto":"Qui est le gardien d'une chose ?","verso":"Celui qui en a l'usage, la direction et le contrôle (arrêt Franck, 1941). Le propriétaire à qui la chose a été volée n'en est plus le gardien."},{"id":"seed-fc-l2-exoneration-gardien","matiere":"Responsabilité civile","recto":"Comment le gardien d'une chose peut-il s'exonérer ?","verso":"Totalement en prouvant un cas fortuit, une force majeure ou une cause étrangère qui ne lui est pas imputable ; prouver qu'il n'a pas commis de faute ne suffit pas (arrêt Jand'heur). La faute de la victime peut l'exonérer en partie : l'arrêt Desmares (1982) l'avait refusé, il a été abandonné en 1987."},{"id":"seed-fc-l2-parents","matiere":"Responsabilité civile","recto":"Les parents peuvent-ils échapper à leur responsabilité en prouvant qu'ils n'ont commis aucune faute ?","verso":"Non : ils sont responsables de plein droit du dommage causé par leur enfant mineur (art. 1242 C. civ.) et ne s'exonèrent qu'en prouvant la force majeure ou la faute de la victime (arrêt Bertrand, 1997)."},{"id":"seed-fc-l2-commettant","matiere":"Responsabilité civile","recto":"Le préposé qui cause un dommage dans le cadre de sa mission est-il personnellement responsable envers la victime ?","verso":"Non, s'il n'excède pas les limites de sa mission : seul le commettant répond (art. 1242 C. civ. ; arrêt Costedoat, 2000). Mais le préposé condamné pour une infraction intentionnelle engage sa responsabilité (arrêt Cousin, 2001)."},{"id":"seed-fc-l2-blieck","matiere":"Responsabilité civile","recto":"Peut-on être responsable du fait d'autrui en dehors des cas énumérés par le Code civil ?","verso":"Oui : avec l'arrêt Blieck (1991), une association qui a accepté d'organiser et de contrôler à titre permanent le mode de vie d'une personne handicapée doit répondre des dommages qu'elle cause."},{"id":"seed-fc-l2-derguini","matiere":"Responsabilité civile","recto":"Un très jeune enfant peut-il commettre une faute qui réduit son droit à réparation ?","verso":"Oui : la faute de la victime peut être retenue contre un enfant en bas âge sans qu'il soit capable de discerner la portée de son acte (arrêt Derguini, 1984)."},{"id":"seed-fc-l2-voisinage","matiere":"Responsabilité civile","recto":"Qui répond d'un trouble anormal de voisinage, et faut-il une faute ?","verso":"Celui qui est à l'origine d'un trouble excédant les inconvénients normaux de voisinage (propriétaire, locataire, occupant, maître d'ouvrage…) en est responsable de plein droit, sans faute (art. 1253 C. civ., depuis 2024 ; principe posé par la jurisprudence auparavant)."},{"id":"seed-fc-l2-produits","matiere":"Responsabilité civile","recto":"Quand un produit est-il défectueux, et qui en répond ?","verso":"Quand il n'offre pas la sécurité à laquelle on peut légitimement s'attendre (art. 1245-3 C. civ.). Le producteur est responsable du dommage causé par ce défaut, qu'il soit ou non lié par un contrat avec la victime (art. 1245 C. civ.)."},{"id":"seed-fc-l2-cadot","matiere":"Droit administratif","recto":"Que décide l'arrêt Cadot (1889) ?","verso":"Il abandonne la théorie du « ministre-juge » : le Conseil d'État devient compétent pour connaître directement de toutes les affaires administratives, comme juge de droit commun."},{"id":"seed-fc-l2-delai-rep","matiere":"Droit administratif","recto":"Dans quel délai faut-il attaquer une décision administrative devant le juge ?","verso":"Deux mois à partir de la notification ou de la publication de la décision (art. R. 421-1 CJA)."},{"id":"seed-fc-l2-lamotte","matiere":"Droit administratif","recto":"Le recours pour excès de pouvoir existe-t-il même sans texte qui le prévoie ?","verso":"Oui : il est ouvert même sans texte contre tout acte administratif ; seule une disposition législative expresse peut l'exclure, et le juge l'interprète strictement (arrêt Dame Lamotte, 1950)."},{"id":"seed-fc-l2-refere-suspension","matiere":"Droit administratif","recto":"À quelles conditions le juge des référés peut-il suspendre une décision administrative ?","verso":"Une requête en annulation ou en réformation doit être déposée ; il faut l'urgence et un moyen propre à créer un doute sérieux sur la légalité de la décision (art. L. 521-1 CJA)."},{"id":"seed-fc-l2-refere-liberte","matiere":"Droit administratif","recto":"Qu'est-ce que le référé-liberté ?","verso":"En cas d'urgence, le juge des référés ordonne toute mesure nécessaire à la sauvegarde d'une liberté fondamentale à laquelle l'administration a porté une atteinte grave et manifestement illégale ; il se prononce en quarante-huit heures (art. L. 521-2 CJA)."},{"id":"seed-fc-l2-silence","matiere":"Droit administratif","recto":"Que vaut, en principe, le silence gardé deux mois par l'administration sur une demande ?","verso":"Une décision d'acceptation (art. L. 231-1 du Code des relations entre le public et l'administration). Des textes prévoient des exceptions où le silence vaut rejet."},{"id":"seed-fc-l2-retrait","matiere":"Droit administratif","recto":"L'administration peut-elle retirer une décision créatrice de droits ?","verso":"Seulement si elle est illégale, et dans les quatre mois qui suivent la décision (art. L. 242-1 CRPA). La règle vient de l'arrêt Ternon (2001)."},{"id":"seed-fc-l2-labonne","matiere":"Droit administratif","recto":"Que reconnaît l'arrêt Labonne (1919) ?","verso":"Le chef de l'État tient de ses attributions constitutionnelles le pouvoir de réglementer la police à l'échelle nationale, sans habilitation législative. Sous la Ve République, ce pouvoir de police générale appartient au Premier ministre (art. 21 de la Constitution)."},{"id":"seed-fc-l2-lutetia","matiere":"Droit administratif","recto":"Un maire peut-il interdire dans sa commune un film qui a reçu le visa national ?","verso":"Oui, en vertu de ses pouvoirs de police et en raison de circonstances locales exceptionnelles, si la projection risque d'entraîner des troubles sérieux ou d'être préjudiciable à l'ordre public (arrêt Société des films Lutétia, 1959)."},{"id":"seed-fc-l2-couiteas","matiere":"Droit administratif","recto":"L'État peut-il devoir indemniser sans avoir commis de faute ?","verso":"Oui : quand une décision légale fait peser sur une personne une charge qu'elle n'a pas à supporter, la rupture de l'égalité devant les charges publiques est indemnisée (arrêt Couitéas, 1923, refus légal du concours de la force publique)."},{"id":"seed-fc-l2-imprevision-admin","matiere":"Droit administratif","recto":"Qu'est-ce que la théorie de l'imprévision en droit administratif ?","verso":"Quand un événement imprévisible, extérieur aux parties, bouleverse l'économie d'un contrat administratif, le cocontractant doit poursuivre le service et peut obtenir une indemnité d'imprévision (arrêt Compagnie générale d'éclairage de Bordeaux, 1916)."},{"id":"seed-fc-l2-cumul","matiere":"Droit administratif","recto":"Faute personnelle de l'agent et faute de service peuvent-elles se cumuler ?","verso":"Oui : la faute personnelle n'exclut pas la faute de service. La victime peut agir contre l'administration, qui dispose ensuite d'une action récursoire contre l'agent (arrêts Anguet, 1911, et Époux Lemonnier, 1918)."},{"id":"seed-fc-l2-classification","matiere":"Droit pénal général","recto":"Les infractions pénales sont classées, suivant leur gravité, en crimes, délits et contraventions.","verso":"Art. 111-1 du Code pénal."},{"id":"seed-fc-l2-legalite","matiere":"Droit pénal général","recto":"Que dit le principe de légalité des délits et des peines ?","verso":"Nul ne peut être puni pour un crime ou un délit dont les éléments ne sont pas définis par la loi, ni pour une contravention que le règlement ne définit pas ; la peine doit aussi être prévue par la loi ou le règlement (art. 111-3 C. pén.)."},{"id":"seed-fc-l2-interpretation","matiere":"Droit pénal général","recto":"La loi pénale est d'interprétation stricte.","verso":"Art. 111-4 du Code pénal. Exemple : l'homicide involontaire n'a pas été étendu à l'enfant à naître (Ass. plén., 2001)."},{"id":"seed-fc-l2-retroactivite","matiere":"Droit pénal général","recto":"Une loi pénale nouvelle plus douce s'applique-t-elle à des faits commis avant elle ?","verso":"Oui, si ces faits n'ont pas encore donné lieu à une condamnation passée en force de chose jugée : c'est la rétroactivité de la loi pénale plus douce. Une loi plus sévère, elle, ne s'applique qu'aux faits postérieurs (art. 112-1 C. pén.)."},{"id":"seed-fc-l2-propre-fait","matiere":"Droit pénal général","recto":"Nul n'est responsable pénalement que de son propre fait.","verso":"Art. 121-1 du Code pénal."},{"id":"seed-fc-l2-intention","matiere":"Droit pénal général","recto":"Un délit peut-il exister sans intention de le commettre ?","verso":"En principe non (art. 121-3 C. pén.), sauf lorsque la loi le prévoit : mise en danger délibérée de la personne d'autrui, ou faute d'imprudence, de négligence ou de manquement à une obligation de prudence ou de sécurité."},{"id":"seed-fc-l2-tentative","matiere":"Droit pénal général","recto":"Quand y a-t-il tentative punissable ?","verso":"Lorsqu'elle est manifestée par un commencement d'exécution et n'a été suspendue ou n'a manqué son effet qu'en raison de circonstances indépendantes de la volonté de son auteur (art. 121-5 C. pén.)."},{"id":"seed-fc-l2-complicite","matiere":"Droit pénal général","recto":"Quelles sont les formes de la complicité ?","verso":"L'aide ou l'assistance apportée sciemment à la préparation ou à la consommation d'un crime ou d'un délit, et la provocation (don, promesse, menace, ordre, abus d'autorité ou de pouvoir) ou les instructions données pour le commettre (art. 121-7 C. pén.). Sans fait principal punissable, pas de complicité (arrêt Lacour, 1962)."},{"id":"seed-fc-l2-trouble-psychique","matiere":"Droit pénal général","recto":"Abolition ou altération du discernement : quelle différence pour la responsabilité pénale ?","verso":"Un trouble psychique ou neuropsychique qui a aboli le discernement rend la personne pénalement irresponsable ; s'il l'a seulement altéré, elle reste punissable, mais la juridiction en tient compte pour fixer la peine (art. 122-1 C. pén.)."},{"id":"seed-fc-l2-legitime-defense","matiere":"Droit pénal général","recto":"Quelles sont les conditions de la légitime défense d'une personne ?","verso":"Une atteinte injustifiée envers soi ou autrui, un acte de défense accompli dans le même temps et commandé par la nécessité, et des moyens qui ne soient pas disproportionnés à la gravité de l'atteinte (art. 122-5 C. pén.)."},{"id":"seed-fc-l2-necessite","matiere":"Droit pénal général","recto":"Qu'est-ce que l'état de nécessité ?","verso":"N'est pas responsable la personne qui, face à un danger actuel ou imminent pour elle-même, autrui ou un bien, accomplit un acte nécessaire à leur sauvegarde, sauf disproportion avec la gravité de la menace (art. 122-7 C. pén.). Il trouve son origine dans le jugement Ménard (1898)."},{"id":"seed-fc-l3-meubles-immeubles","matiere":"Droit des biens","recto":"Tous les biens sont meubles ou immeubles.","verso":"Art. 516 du Code civil : la summa divisio des biens."},{"id":"seed-fc-l3-propriete","matiere":"Droit des biens","recto":"Comment le Code civil définit-il la propriété ?","verso":"Le droit de jouir et disposer des choses de la manière la plus absolue, pourvu qu'on n'en fasse pas un usage prohibé par les lois ou les règlements (art. 544 C. civ.)."},{"id":"seed-fc-l3-expropriation","matiere":"Droit des biens","recto":"Peut-on être contraint de céder sa propriété ?","verso":"Seulement pour cause d'utilité publique, et moyennant une juste et préalable indemnité (art. 545 C. civ.)."},{"id":"seed-fc-l3-usufruit","matiere":"Droit des biens","recto":"Qu'est-ce que l'usufruit ?","verso":"Le droit de jouir des choses dont un autre a la propriété, comme le propriétaire lui-même, mais à charge d'en conserver la substance (art. 578 C. civ.)."},{"id":"seed-fc-l3-indivision","matiere":"Droit des biens","recto":"Nul ne peut être contraint à demeurer dans l'indivision et le partage peut toujours être provoqué, à moins qu'il n'y ait été sursis par jugement ou convention.","verso":"Art. 815 du Code civil."},{"id":"seed-fc-l3-possession-qualites","matiere":"Droit des biens","recto":"Quelles qualités la possession doit-elle avoir pour permettre de prescrire ?","verso":"Elle doit être continue et non interrompue, paisible, publique, non équivoque, et à titre de propriétaire (art. 2261 C. civ.)."},{"id":"seed-fc-l3-usucapion","matiere":"Droit des biens","recto":"Au bout de combien de temps peut-on acquérir un immeuble par la possession ?","verso":"Trente ans ; dix ans seulement pour celui qui acquiert de bonne foi et par juste titre (art. 2272 C. civ.)."},{"id":"seed-fc-l3-meubles-possession","matiere":"Droit des biens","recto":"En fait de meubles, la possession vaut titre.","verso":"Art. 2276 du Code civil ; le propriétaire d'une chose perdue ou volée peut la revendiquer pendant trois ans."},{"id":"seed-fc-l3-empietement","matiere":"Droit des biens","recto":"Le propriétaire victime d'un empiètement, même minime, peut-il obtenir la démolition ?","verso":"Oui : la défense du droit de propriété contre un empiètement ne dégénère pas en abus ; il obtient la suppression de l'ouvrage, sans que le juge apprécie la gravité de l'atteinte (Cass. 3e civ., 1990)."},{"id":"seed-fc-l3-image-biens","matiere":"Droit des biens","recto":"Le propriétaire d'une chose a-t-il un droit exclusif sur son image ?","verso":"Non : il peut seulement s'opposer à l'utilisation de cette image par un tiers si elle lui cause un trouble anormal (arrêt Hôtel de Girancourt, 2004)."},{"id":"seed-fc-l3-dispositif","matiere":"Procédure civile","recto":"Le juge doit se prononcer sur tout ce qui est demandé et seulement sur ce qui est demandé.","verso":"Art. 5 du Code de procédure civile : le juge ne statue ni infra ni ultra petita."},{"id":"seed-fc-l3-faits","matiere":"Procédure civile","recto":"À qui revient-il d'alléguer les faits, puis de les prouver ?","verso":"Aux parties : elles ont la charge d'alléguer les faits propres à fonder leurs prétentions (art. 6 CPC) et de prouver ceux qui sont nécessaires au succès de leur prétention (art. 9 CPC)."},{"id":"seed-fc-l3-audition","matiere":"Procédure civile","recto":"Nulle partie ne peut être jugée sans avoir été entendue ou appelée.","verso":"Art. 14 du Code de procédure civile."},{"id":"seed-fc-l3-contradictoire","matiere":"Procédure civile","recto":"Le juge peut-il fonder sa décision sur un moyen de droit qu'il relève d'office ?","verso":"Seulement après avoir invité les parties à présenter leurs observations : il doit observer lui-même le principe de la contradiction (art. 16 CPC)."},{"id":"seed-fc-l3-interet","matiere":"Procédure civile","recto":"Qui peut agir en justice ?","verso":"Tous ceux qui ont un intérêt légitime au succès ou au rejet d'une prétention, sauf lorsque la loi réserve l'action à certaines personnes qualifiées (art. 31 CPC)."},{"id":"seed-fc-l3-exceptions","matiere":"Procédure civile","recto":"Qu'est-ce qu'une exception de procédure, et quand faut-il la soulever ?","verso":"Un moyen qui tend à faire déclarer la procédure irrégulière ou éteinte, ou à en suspendre le cours (art. 73 CPC). Elle doit être soulevée, à peine d'irrecevabilité, avant toute défense au fond ou fin de non-recevoir, et en même temps que les autres exceptions (art. 74 CPC)."},{"id":"seed-fc-l3-fin-non-recevoir","matiere":"Procédure civile","recto":"Qu'est-ce qu'une fin de non-recevoir ? Donnez des exemples.","verso":"Un moyen qui tend à faire déclarer l'adversaire irrecevable, sans examen au fond, pour défaut de droit d'agir : défaut de qualité ou d'intérêt, prescription, délai préfix, chose jugée (art. 122 CPC)."},{"id":"seed-fc-l3-refere","matiere":"Procédure civile","recto":"Que peut ordonner le juge des référés en cas d'urgence ?","verso":"Toutes les mesures qui ne se heurtent à aucune contestation sérieuse ou que justifie l'existence d'un différend (art. 834 CPC)."},{"id":"seed-fc-l3-chose-jugee","matiere":"Procédure civile","recto":"À quelles conditions l'autorité de la chose jugée s'oppose-t-elle à une nouvelle demande ?","verso":"Il faut la même chose demandée, la même cause et les mêmes parties, agissant en la même qualité (art. 1355 C. civ.)."},{"id":"seed-fc-l3-cesareo","matiere":"Procédure civile","recto":"Que décide l'arrêt Cesareo (2006) sur les moyens d'une demande ?","verso":"Le demandeur doit présenter dès la première instance tous les moyens qu'il estime de nature à fonder sa demande ; il ne peut pas en invoquer un nouveau dans une instance postérieure (concentration des moyens)."},{"id":"seed-fc-l3-effet-direct","matiere":"Droit de l'Union européenne","recto":"Que pose l'arrêt Van Gend en Loos (1963) ?","verso":"L'effet direct : le droit communautaire crée des droits et obligations pour les particuliers, que les juridictions nationales doivent sauvegarder ; la Communauté constitue un nouvel ordre juridique."},{"id":"seed-fc-l3-primaute","matiere":"Droit de l'Union européenne","recto":"Que consacre l'arrêt Costa c. ENEL (1964) ?","verso":"La primauté du droit communautaire : issu d'une source autonome, il ne peut se voir opposer un texte interne quel qu'il soit, antérieur ou postérieur."},{"id":"seed-fc-l3-simmenthal","matiere":"Droit de l'Union européenne","recto":"Que doit faire le juge national face à une loi contraire au droit de l'Union, selon l'arrêt Simmenthal (1978) ?","verso":"La laisser inappliquée de lui-même, même si elle est postérieure, sans demander ni attendre son élimination préalable."},{"id":"seed-fc-l3-renvoi-prejudiciel","matiere":"Droit de l'Union européenne","recto":"Qu'est-ce que le renvoi préjudiciel ?","verso":"La Cour de justice de l'Union européenne statue à titre préjudiciel sur l'interprétation des traités et sur la validité et l'interprétation des actes de l'Union ; une juridiction nationale peut la saisir si elle l'estime nécessaire pour rendre son jugement (art. 267 TFUE)."},{"id":"seed-fc-l3-restrictions","matiere":"Droit de l'Union européenne","recto":"Les restrictions quantitatives à l'importation ainsi que toutes mesures d'effet équivalent, sont interdites entre les États membres.","verso":"Art. 34 du TFUE."},{"id":"seed-fc-l3-dassonville","matiere":"Droit de l'Union européenne","recto":"Qu'est-ce qu'une mesure d'effet équivalent, selon l'arrêt Dassonville (1974) ?","verso":"Toute réglementation commerciale des États membres susceptible d'entraver directement ou indirectement, actuellement ou potentiellement, le commerce entre États membres."},{"id":"seed-fc-l3-cassis","matiere":"Droit de l'Union européenne","recto":"Que pose l'arrêt Cassis de Dijon (1979) ?","verso":"La reconnaissance mutuelle : un produit légalement fabriqué et commercialisé dans un État membre doit pouvoir circuler dans les autres, sauf exigences impératives (santé, loyauté des transactions, protection du consommateur) proportionnées."},{"id":"seed-fc-l3-francovich","matiere":"Droit de l'Union européenne","recto":"Un particulier peut-il obtenir réparation d'un État qui viole le droit de l'Union ?","verso":"Oui : la responsabilité de l'État pour les dommages causés par les violations qui lui sont imputables est inhérente au traité ; pour une directive non transposée, elle doit conférer des droits identifiables et il faut un lien de causalité (arrêt Francovich, 1991)."},{"id":"seed-fc-l3-marshall","matiere":"Droit de l'Union européenne","recto":"Une directive peut-elle être invoquée contre un particulier ?","verso":"Non : par elle-même, elle ne crée pas d'obligations à la charge d'un particulier (pas d'effet direct horizontal) ; elle peut être invoquée contre l'État, même en sa qualité d'employeur (arrêt Marshall, 1986)."},{"id":"seed-fc-l3-mariage","matiere":"Droit de la famille","recto":"Le mariage est contracté par deux personnes de sexe différent ou de même sexe.","verso":"Art. 143 du Code civil, depuis la loi du 17 mai 2013."},{"id":"seed-fc-l3-age-mariage","matiere":"Droit de la famille","recto":"À partir de quel âge peut-on se marier ?","verso":"Dix-huit ans révolus (art. 144 C. civ.)."},{"id":"seed-fc-l3-devoirs-epoux","matiere":"Droit de la famille","recto":"Les époux se doivent mutuellement respect, fidélité, secours, assistance.","verso":"Art. 212 du Code civil."},{"id":"seed-fc-l3-cas-divorce","matiere":"Droit de la famille","recto":"Quels sont les cas de divorce ?","verso":"Le consentement mutuel par acte sous signature privée contresigné par avocats et déposé chez un notaire ; et, devant le juge, le consentement mutuel (cas particulier), l'acceptation du principe de la rupture, l'altération définitive du lien conjugal et la faute (art. 229 C. civ.)."},{"id":"seed-fc-l3-divorce-avocats","matiere":"Droit de la famille","recto":"Comment se fait un divorce par consentement mutuel sans juge ?","verso":"Les époux, assistés chacun par un avocat, constatent leur accord sur la rupture et ses effets dans une convention contresignée par leurs avocats, puis déposée au rang des minutes d'un notaire, qui contrôle les exigences de forme (art. 229-1 C. civ.)."},{"id":"seed-fc-l3-maternite","matiere":"Droit de la famille","recto":"Comment la filiation s'établit-elle à l'égard de la mère ?","verso":"Par la désignation de la mère dans l'acte de naissance de l'enfant (art. 311-25 C. civ.)."},{"id":"seed-fc-l3-paternite","matiere":"Droit de la famille","recto":"L'enfant conçu ou né pendant le mariage a pour père le mari.","verso":"Art. 312 du Code civil : la présomption de paternité."},{"id":"seed-fc-l3-autorite-parentale","matiere":"Droit de la famille","recto":"Qu'est-ce que l'autorité parentale ?","verso":"Un ensemble de droits et de devoirs ayant pour finalité l'intérêt de l'enfant ; elle appartient aux parents jusqu'à sa majorité ou son émancipation, pour le protéger dans sa sécurité, sa santé, sa vie privée et sa moralité, assurer son éducation et permettre son développement ; elle s'exerce sans violences physiques ou psychologiques (art. 371-1 C. civ.)."},{"id":"seed-fc-l3-pacs","matiere":"Droit de la famille","recto":"Qu'est-ce qu'un pacte civil de solidarité ?","verso":"Un contrat conclu par deux personnes physiques majeures, de sexe différent ou de même sexe, pour organiser leur vie commune (art. 515-1 C. civ.)."},{"id":"seed-fc-m1-droit-de-gage-general","matiere":"Droit des sûretés","recto":"Quiconque s'est obligé personnellement, est tenu de remplir son engagement sur tous ses biens mobiliers et immobiliers, présents et à venir.","verso":"Art. 2284 du Code civil : le droit de gage général des créanciers."},{"id":"seed-fc-m1-gage-commun","matiere":"Droit des sûretés","recto":"Comment se répartit le prix des biens du débiteur entre ses créanciers ?","verso":"Les biens du débiteur sont le gage commun de ses créanciers ; le prix se distribue entre eux par contribution, sauf causes légitimes de préférence (art. 2285 C. civ.)."},{"id":"seed-fc-m1-surete-reelle","matiere":"Droit des sûretés","recto":"Qu'est-ce qu'une sûreté réelle ?","verso":"L'affectation d'un bien ou d'un ensemble de biens, présents ou futurs, au paiement préférentiel ou exclusif du créancier (art. 2323 C. civ.)."},{"id":"seed-fc-m1-cautionnement","matiere":"Droit des sûretés","recto":"Le cautionnement est le contrat par lequel une caution s'oblige envers le créancier à payer la dette du débiteur en cas de défaillance de celui-ci.","verso":"Art. 2288 du Code civil, depuis la réforme du 15 septembre 2021 ; il peut être souscrit même à l'insu du débiteur."},{"id":"seed-fc-m1-mention-caution","matiere":"Droit des sûretés","recto":"Quelle formalité la caution personne physique doit-elle accomplir, et à quelle sanction ?","verso":"Apposer elle-même la mention qu'elle s'engage à payer au créancier ce que lui doit le débiteur en cas de défaillance, dans la limite d'un montant écrit en toutes lettres et en chiffres, à peine de nullité de son engagement ; en cas de différence, la somme en lettres l'emporte (art. 2297 C. civ.)."},{"id":"seed-fc-m1-disproportion","matiere":"Droit des sûretés","recto":"Que devient le cautionnement manifestement disproportionné souscrit par une personne physique envers un créancier professionnel ?","verso":"Il est réduit au montant à hauteur duquel la caution pouvait s'engager à la date de sa conclusion (art. 2300 C. civ., depuis 2021). Avant la loi, l'arrêt Macron (1997) sanctionnait déjà la banque par la responsabilité."},{"id":"seed-fc-m1-exceptions-caution","matiere":"Droit des sûretés","recto":"La caution peut-elle opposer au créancier les exceptions du débiteur ?","verso":"Oui, toutes les exceptions, personnelles ou inhérentes à la dette ; mais pas les mesures légales ou judiciaires dont le débiteur bénéficie du fait de sa défaillance, sauf disposition spéciale contraire (art. 2298 C. civ.)."},{"id":"seed-fc-m1-information-annuelle","matiere":"Droit des sûretés","recto":"Que doit faire chaque année le créancier professionnel envers la caution personne physique ?","verso":"Lui faire connaître, avant le 31 mars et à ses frais, le montant de la dette restant due au 31 décembre précédent, sous peine de déchéance des intérêts et pénalités échus depuis la précédente information (art. 2302 C. civ.)."},{"id":"seed-fc-m1-gage","matiere":"Droit des sûretés","recto":"Qu'est-ce que le gage ?","verso":"Une convention par laquelle le constituant accorde à un créancier le droit de se faire payer par préférence à ses autres créanciers sur un bien mobilier ou un ensemble de biens mobiliers corporels, présents ou futurs (art. 2333 C. civ.)."},{"id":"seed-fc-m1-attribution-gage","matiere":"Droit des sûretés","recto":"Faute de paiement, quelles voies s'ouvrent au créancier gagiste ?","verso":"Poursuivre la vente du bien gagé (art. 2346 C. civ.) ou faire ordonner en justice que le bien lui demeure en paiement, en reversant l'excédent de valeur au constituant (art. 2347 C. civ.)."},{"id":"seed-fc-m1-conciliation","matiere":"Entreprises en difficulté","recto":"Quel débiteur peut demander une conciliation ?","verso":"Celui qui exerce une activité commerciale ou artisanale, éprouve une difficulté juridique, économique ou financière, avérée ou prévisible, et n'est pas en cessation des paiements depuis plus de quarante-cinq jours (art. L. 611-4 C. com.)."},{"id":"seed-fc-m1-sauvegarde","matiere":"Entreprises en difficulté","recto":"À quelle condition une procédure de sauvegarde peut-elle être ouverte ?","verso":"Sur demande du débiteur qui, sans être en cessation des paiements, justifie de difficultés qu'il n'est pas en mesure de surmonter (art. L. 620-1 C. com.)."},{"id":"seed-fc-m1-cessation-paiements","matiere":"Entreprises en difficulté","recto":"Qu'est-ce que la cessation des paiements ?","verso":"L'impossibilité de faire face au passif exigible avec l'actif disponible ; le débiteur dont les réserves de crédit ou les moratoires permettent d'y faire face n'est pas en cessation des paiements (art. L. 631-1 C. com.)."},{"id":"seed-fc-m1-delai-45-jours","matiere":"Entreprises en difficulté","recto":"Dans quel délai le débiteur doit-il demander l'ouverture d'un redressement judiciaire ?","verso":"Au plus tard dans les quarante-cinq jours qui suivent la cessation des paiements, s'il n'a pas demandé dans ce délai l'ouverture d'une conciliation (art. L. 631-4 C. com.)."},{"id":"seed-fc-m1-liquidation","matiere":"Entreprises en difficulté","recto":"Quand ouvre-t-on une liquidation judiciaire ?","verso":"Lorsque le débiteur est en cessation des paiements et que son redressement est manifestement impossible ; elle met fin à l'activité ou réalise le patrimoine du débiteur (art. L. 640-1 C. com.)."},{"id":"seed-fc-m1-interdiction-payer","matiere":"Entreprises en difficulté","recto":"Le débiteur peut-il payer ses créanciers antérieurs après le jugement d'ouverture ?","verso":"Non : le jugement emporte de plein droit interdiction de payer toute créance née antérieurement, sauf paiement par compensation de créances connexes ; les créances alimentaires échappent à cette interdiction (art. L. 622-7 C. com.)."},{"id":"seed-fc-m1-arret-poursuites","matiere":"Entreprises en difficulté","recto":"Quel est l'effet du jugement d'ouverture sur les actions des créanciers antérieurs ?","verso":"Il interrompt ou interdit les actions tendant à la condamnation du débiteur au paiement d'une somme d'argent ou à la résolution d'un contrat pour défaut de paiement, et arrête ou interdit les procédures d'exécution (art. L. 622-21 C. com.)."},{"id":"seed-fc-m1-declaration-creances","matiere":"Entreprises en difficulté","recto":"Dans quel délai les créanciers doivent-ils déclarer leurs créances, et à qui ?","verso":"Au mandataire judiciaire (art. L. 622-24 C. com.), dans les deux mois de la publication du jugement d'ouverture au Bulletin officiel des annonces civiles et commerciales, délai augmenté de deux mois pour les créanciers établis hors de France métropolitaine (art. R. 622-24 C. com.)."},{"id":"seed-fc-m1-periode-observation","matiere":"Entreprises en difficulté","recto":"Que doit décider le tribunal dans les deux mois du jugement ouvrant un redressement judiciaire ?","verso":"S'il ordonne la poursuite de la période d'observation, ce qu'il fait lorsque le débiteur dispose de capacités de financement suffisantes (art. L. 631-15 C. com.)."},{"id":"seed-fc-m1-duree-plan","matiere":"Entreprises en difficulté","recto":"Quelle est la durée maximale d'un plan de sauvegarde ?","verso":"Dix ans, fixés par le tribunal ; quinze ans pour un débiteur exerçant une activité agricole (art. L. 626-12 C. com.)."},{"id":"seed-fc-m1-delai-recours","matiere":"Contentieux administratif","recto":"La juridiction ne peut être saisie que par voie de recours formé contre une décision, et ce, dans les deux mois à partir de la notification ou de la publication de la décision attaquée.","verso":"Art. R. 421-1 du Code de justice administrative."},{"id":"seed-fc-m1-mention-voies","matiere":"Contentieux administratif","recto":"À quelle condition le délai de recours est-il opposable ?","verso":"Il faut que la notification de la décision mentionne ce délai et les voies de recours (art. R. 421-5 CJA)."},{"id":"seed-fc-m1-czabaj","matiere":"Contentieux administratif","recto":"Sans mention des voies et délais, une décision peut-elle être contestée indéfiniment ?","verso":"Non : la sécurité juridique impose d'agir dans un délai raisonnable, en principe un an à compter de la connaissance de la décision (arrêt Czabaj, 2016)."},{"id":"seed-fc-m1-refere-provisoire","matiere":"Contentieux administratif","recto":"Le juge des référés statue par des mesures qui présentent un caractère provisoire.","verso":"Art. L. 511-1 du Code de justice administrative : il n'est pas saisi du principal et se prononce dans les meilleurs délais."},{"id":"seed-fc-m1-refere-suspension","matiere":"Contentieux administratif","recto":"Quelles sont les conditions du référé-suspension ?","verso":"Une requête en annulation ou en réformation contre la décision, l'urgence, et un moyen propre à créer, en l'état de l'instruction, un doute sérieux quant à sa légalité (art. L. 521-1 CJA)."},{"id":"seed-fc-m1-refere-liberte","matiere":"Contentieux administratif","recto":"Que permet le référé-liberté, et en combien de temps le juge statue-t-il ?","verso":"Ordonner toutes mesures nécessaires à la sauvegarde d'une liberté fondamentale à laquelle l'administration a porté une atteinte grave et manifestement illégale, en cas d'urgence ; le juge se prononce dans les quarante-huit heures (art. L. 521-2 CJA)."},{"id":"seed-fc-m1-refere-mesures-utiles","matiere":"Contentieux administratif","recto":"Qu'est-ce que le référé « mesures utiles » ?","verso":"En cas d'urgence, sur simple requête recevable même sans décision préalable, le juge peut ordonner toutes autres mesures utiles, sans faire obstacle à l'exécution d'une décision administrative (art. L. 521-3 CJA)."},{"id":"seed-fc-m1-injonction","matiere":"Contentieux administratif","recto":"Le juge administratif peut-il enjoindre à l'administration de prendre une mesure ?","verso":"Oui : lorsque sa décision implique nécessairement une mesure d'exécution dans un sens déterminé, il la prescrit, le cas échéant avec un délai, sur conclusions ou d'office (art. L. 911-1 CJA)."},{"id":"seed-fc-m1-danthony","matiere":"Contentieux administratif","recto":"Un vice de procédure entraîne-t-il toujours l'annulation de la décision ?","verso":"Non : seulement s'il a pu exercer une influence sur le sens de la décision ou s'il a privé les intéressés d'une garantie (arrêt Danthony, 2011)."},{"id":"seed-fc-m1-tarn-et-garonne","matiere":"Contentieux administratif","recto":"Un tiers peut-il contester la validité d'un contrat administratif ?","verso":"Oui : tout tiers susceptible d'être lésé de façon suffisamment directe et certaine par sa passation ou ses clauses peut former un recours de plein contentieux, dans les deux mois suivant les mesures de publicité appropriées (arrêt Département de Tarn-et-Garonne, 2014)."},{"id":"seed-fc-m2-bail-duree","matiere":"Baux commerciaux","recto":"La durée du contrat de location ne peut être inférieure à neuf ans.","verso":"Art. L. 145-4 du Code de commerce ; le preneur peut donner congé à l'expiration de chaque période triennale, au moins six mois à l'avance."},{"id":"seed-fc-m2-bail-derogatoire","matiere":"Baux commerciaux","recto":"Peut-on échapper au statut des baux commerciaux ?","verso":"Oui, à l'entrée dans les lieux, par un bail dérogatoire dont la durée totale, baux successifs compris, ne dépasse pas trois ans ; si le preneur reste et est laissé en possession plus d'un mois après l'échéance, un bail soumis au statut prend naissance (art. L. 145-5 C. com.)."},{"id":"seed-fc-m2-exploitation-effective","matiere":"Baux commerciaux","recto":"Qui peut invoquer le droit au renouvellement ?","verso":"Le propriétaire du fonds exploité dans les lieux ; sauf motifs légitimes, le fonds doit avoir été effectivement exploité au cours des trois années précédant l'expiration du bail ou de sa prolongation (art. L. 145-8 C. com.)."},{"id":"seed-fc-m2-conge","matiere":"Baux commerciaux","recto":"Comment prend fin un bail commercial ?","verso":"Seulement par un congé donné six mois à l'avance ou par une demande de renouvellement ; à défaut, le bail écrit se prolonge tacitement, et le congé doit alors être donné six mois à l'avance pour le dernier jour du trimestre civil (art. L. 145-9 C. com.)."},{"id":"seed-fc-m2-demande-renouvellement","matiere":"Baux commerciaux","recto":"Quand le locataire peut-il demander le renouvellement, et sous quelle forme ?","verso":"Dans les six mois qui précèdent l'expiration du bail ou à tout moment au cours de sa prolongation, par acte extrajudiciaire ou par lettre recommandée avec demande d'avis de réception (art. L. 145-10 C. com.)."},{"id":"seed-fc-m2-indemnite-eviction","matiere":"Baux commerciaux","recto":"Le bailleur peut-il refuser le renouvellement ?","verso":"Oui, mais il doit en principe payer au locataire évincé une indemnité d'éviction égale au préjudice causé, comprenant notamment la valeur marchande du fonds et les frais de déménagement et de réinstallation (art. L. 145-14 C. com.)."},{"id":"seed-fc-m2-motif-grave","matiere":"Baux commerciaux","recto":"Quand le bailleur peut-il refuser le renouvellement sans indemnité pour un manquement du locataire ?","verso":"S'il justifie d'un motif grave et légitime ; pour l'inexécution d'une obligation ou l'arrêt injustifié de l'exploitation, l'infraction doit s'être poursuivie plus d'un mois après une mise en demeure délivrée par acte extrajudiciaire, à peine de nullité (art. L. 145-17 C. com.)."},{"id":"seed-fc-m2-clause-resolutoire","matiere":"Baux commerciaux","recto":"Quand la clause résolutoire d'un bail commercial produit-elle effet ?","verso":"Un mois après un commandement demeuré infructueux, qui doit mentionner ce délai à peine de nullité ; le juge peut accorder des délais et suspendre ses effets (art. L. 145-41 C. com.)."},{"id":"seed-fc-m2-droit-preference","matiere":"Baux commerciaux","recto":"Le locataire commercial est-il prioritaire si le bailleur vend le local ?","verso":"Oui : la notification du projet de vente, qui doit indiquer le prix et les conditions à peine de nullité, vaut offre de vente ; le locataire dispose d'un mois pour se prononcer (art. L. 145-46-1 C. com.)."},{"id":"seed-fc-m2-prescription-baux","matiere":"Baux commerciaux","recto":"Toutes les actions exercées en vertu du présent chapitre se prescrivent par deux ans.","verso":"Art. L. 145-60 du Code de commerce : la prescription biennale du statut des baux commerciaux."},{"id":"seed-fc-m2-consommateur","matiere":"Droit de la consommation","recto":"Qui est consommateur au sens du Code de la consommation ?","verso":"Toute personne physique qui agit à des fins qui n'entrent pas dans le cadre de son activité commerciale, industrielle, artisanale, libérale ou agricole (article liminaire C. consom.)."},{"id":"seed-fc-m2-clause-abusive","matiere":"Droit de la consommation","recto":"Qu'est-ce qu'une clause abusive ?","verso":"Dans un contrat entre professionnel et consommateur, une clause qui crée, au détriment du consommateur, un déséquilibre significatif entre les droits et obligations des parties (art. L. 212-1 C. consom.) ; la règle vaut aussi pour les non-professionnels (art. L. 212-2)."},{"id":"seed-fc-m2-sanction-clause","matiere":"Droit de la consommation","recto":"Les clauses abusives sont réputées non écrites.","verso":"Art. L. 241-1 du Code de la consommation : le contrat subsiste sans elles s'il le peut."},{"id":"seed-fc-m2-office-juge","matiere":"Droit de la consommation","recto":"Le juge peut-il relever d'office le caractère abusif d'une clause ?","verso":"Il le doit : il écarte d'office, après avoir recueilli les observations des parties, une clause dont le caractère abusif ressort des éléments du débat (art. R. 632-1 C. consom.), comme l'avait admis la Cour de justice dans l'arrêt Océano (2000)."},{"id":"seed-fc-m2-retractation","matiere":"Droit de la consommation","recto":"De quel délai le consommateur dispose-t-il pour se rétracter d'un contrat conclu à distance ou hors établissement ?","verso":"Quatorze jours, sans motif ; ils courent de la conclusion du contrat pour une prestation de services, de la réception du bien pour une vente (art. L. 221-18 C. consom.)."},{"id":"seed-fc-m2-retractation-prolongee","matiere":"Droit de la consommation","recto":"Que se passe-t-il si le professionnel n'a pas informé le consommateur de son droit de rétractation ?","verso":"Le délai est prolongé de douze mois à compter de l'expiration du délai initial ; si l'information est donnée pendant cette prolongation, le délai expire quatorze jours après sa réception (art. L. 221-20 C. consom.)."},{"id":"seed-fc-m2-retractation-credit","matiere":"Droit de la consommation","recto":"Peut-on se rétracter d'un crédit à la consommation ?","verso":"Oui, sans motif, dans un délai de quatorze jours calendaires révolus à compter de l'acceptation de l'offre (art. L. 312-19 C. consom.)."},{"id":"seed-fc-m2-garantie-conformite","matiere":"Droit de la consommation","recto":"Pendant combien de temps le vendeur répond-il des défauts de conformité ?","verso":"De ceux qui existent à la délivrance et apparaissent dans les deux ans qui suivent (art. L. 217-3 C. consom.) ; ils sont présumés exister à la délivrance s'ils apparaissent dans les vingt-quatre mois, douze mois pour un bien d'occasion (art. L. 217-7)."},{"id":"seed-fc-m2-prescription-conso","matiere":"Droit de la consommation","recto":"L'action des professionnels, pour les biens ou les services qu'ils fournissent aux consommateurs, se prescrit par deux ans.","verso":"Art. L. 218-2 du Code de la consommation."},{"id":"seed-fc-m2-retractation-exclusions","matiere":"Droit de la consommation","recto":"Le droit de rétractation existe-t-il pour tous les contrats à distance ?","verso":"Non : l'article L. 221-28 en exclut une liste, dont les services pleinement exécutés avant la fin du délai avec l'accord exprès du consommateur, et les biens dont le prix dépend des fluctuations du marché financier."},{"id":"seed-fc-m2-execution-forcee","matiere":"Voies d'exécution","recto":"À quelles conditions un créancier peut-il poursuivre l'exécution forcée ?","verso":"Il doit être muni d'un titre exécutoire constatant une créance liquide et exigible (art. L. 111-2 CPCE)."},{"id":"seed-fc-m2-dix-ans","matiere":"Voies d'exécution","recto":"Pendant combien de temps un jugement peut-il être exécuté ?","verso":"Dix ans, sauf si l'action en recouvrement de la créance se prescrit par un délai plus long ; la règle vaut pour les titres des 1° à 3° de l'art. L. 111-3 (décisions de justice, titres étrangers et sentences déclarés exécutoires, procès-verbaux de conciliation) (art. L. 111-4 CPCE)."},{"id":"seed-fc-m2-proportionnalite","matiere":"Voies d'exécution","recto":"Le créancier choisit-il librement la mesure d'exécution ?","verso":"Oui, mais l'exécution ne peut excéder ce qui se révèle nécessaire pour obtenir le paiement (art. L. 111-7 CPCE)."},{"id":"seed-fc-m2-astreinte","matiere":"Voies d'exécution","recto":"Tout juge peut, même d'office, ordonner une astreinte pour assurer l'exécution de sa décision.","verso":"Art. L. 131-1 du Code des procédures civiles d'exécution ; le juge de l'exécution peut aussi en assortir la décision d'un autre juge."},{"id":"seed-fc-m2-astreinte-provisoire","matiere":"Voies d'exécution","recto":"Une astreinte est-elle provisoire ou définitive ?","verso":"Provisoire, sauf si le juge a précisé son caractère définitif ; une astreinte définitive ne peut être ordonnée qu'après une astreinte provisoire et pour une durée déterminée. Elle est indépendante des dommages-intérêts (art. L. 131-2 CPCE)."},{"id":"seed-fc-m2-saisie-attribution","matiere":"Voies d'exécution","recto":"Quel est l'effet de la saisie-attribution ?","verso":"L'acte de saisie emporte attribution immédiate au saisissant de la créance saisie, à concurrence des sommes pour lesquelles elle est pratiquée ; une saisie ultérieure ou l'ouverture d'une procédure collective ne la remet pas en cause (art. L. 211-2 CPCE)."},{"id":"seed-fc-m2-saisie-vente","matiere":"Voies d'exécution","recto":"Que faut-il pour saisir et vendre les meubles corporels du débiteur ?","verso":"Un titre exécutoire constatant une créance liquide et exigible et la signification préalable d'un commandement ; l'autorisation du juge de l'exécution est requise si les biens sont détenus par un tiers dans ses locaux d'habitation (art. L. 221-1 CPCE)."},{"id":"seed-fc-m2-treve-hivernale","matiere":"Voies d'exécution","recto":"Peut-on expulser un occupant en hiver ?","verso":"Non : il est sursis à toute expulsion non exécutée du 1er novembre au 31 mars, sauf relogement assuré dans des conditions suffisantes ou introduction dans le domicile d'autrui par manœuvres, menaces, voies de fait ou contrainte (art. L. 412-6 CPCE)."},{"id":"seed-fc-m2-mesure-conservatoire","matiere":"Voies d'exécution","recto":"À quelles conditions peut-on obtenir une mesure conservatoire ?","verso":"Une créance qui paraît fondée en son principe et des circonstances susceptibles d'en menacer le recouvrement ; le juge autorise la mesure sans commandement préalable, sous forme de saisie conservatoire ou de sûreté judiciaire (art. L. 511-1 CPCE)."},{"id":"seed-fc-m2-jex","matiere":"Voies d'exécution","recto":"De quoi connaît le juge de l'exécution ?","verso":"De manière exclusive, des difficultés relatives aux titres exécutoires et des contestations nées de l'exécution forcée, même sur le fond du droit ; il autorise aussi les mesures conservatoires et connaît de la saisie immobilière (art. L. 213-6 COJ)."}]};
